Ceviri.ekle("hy","olay",{
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Բիլեջիքն առաջին անգամ է հիշատակվում. Բյուզանդիայի հետ սահմանը սկսվում էր Բիլեջիքից", "7b69f743"], "d": ["Նեշրիի փոխանցած 683 թվականի իրադարձություններում Բիլեջիքը հիշատակվում է որպես այն վայրը, որտեղից սկսվում էր Օսման բեյի սահմանային բեյության և Բյուզանդիայի միջև սահմանը։ Սա բնակավայրի պատմության մեջ հայտնի առաջին հիշատակությունն է, ոչ թե հիմնադրումը։", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Բուրդուրում Ղազան խանի անունով դրամ. քաղաքի առաջին հայտնի վկայությունը", "01974ddc"], "d": ["Համիդօղլուները Իլխանական ճնշման տակ 699 թվականին ստիպված եղան Բուրդուրում Ղազան խանի անունով դրամ հատել։ Այս դրամը Բուրդուրի առաջին գրավոր/թվագրված վկայությունն է։", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Չորումը հիշատակվում է Էրեթնայի երկրում. քաղաքի առաջին հայտնի վկայությունը", "bf7bd67f"], "d": ["Էրեթնա բեյի՝ 753 թվականի Մուհառամին մահվան ժամանակ նրա իշխանության տակ գտնվող քաղաքների շարքում թվարկվում է նաև Չորումը։ Քաղաքի հիմնադրումը հայտնի չէ. այս հիշատակությունը գտնված ամենավաղ թվագրված վկայությունն է։", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Բրաիլան առաջին անգամ է հիշատակվում. Վլայկու Վոդայի արտոնագիրը Բրաշովի վաճառականներին", "0b3517a7"], "d": ["Վալախիայի վոյևոդ Վլադիսլավը Բրաշովի վաճառականներին տվեց փաստաթուղթ, որը դյուրություններ էր շնորհում Բրաիլայի ճանապարհով ապրանք փոխադրելիս։ Այս փաստաթուղթը Բրաիլայի հայտնի առաջին գրավոր վկայությունն է. վայրը այստեղ դեռ ոչ թե որպես քաղաք, այլ որպես ճանապարհի Դանուբի ծայրակետ է հիշատակվում։ Դա հիմնադրման թվական չէ։", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Քիշնևն առաջին անգամ հիշատակվեց Մոլդովայի վոյևոդի հրովարտակում", "a50799d7"], "d": ["Քիշնևի անունն առաջին անգամ հիշատակվում է Մոլդովայի վոյևոդ Ալեքսանդրուի 1420 թվականի մի հրովարտակում։ Քաղաքը երկար ժամանակ մնաց մոլդովական փոքր ավան. 1812 թվականին Բեսարաբիայի հետ միասին Ռուսաստանին անցնելով՝ դարձավ մարզի կենտրոն։", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Գալացն առաջին անգամ հիշատակվում է Մոլդովայի վոյևոդի փաստաթղթում", "a31af8a2"], "d": ["Մոլդովայի վոյևոդ Շտեֆան II-ը Հումորի վանքի՝ Գալացից ձուկ բերող երկու սայլը ազատեց մաքսատուրքից։ Այս փաստաթուղթը Գալացի հաստատ հայտնի առաջին գրավոր վկայությունն է. բնակավայրը կարող էր ավելի վաղ գոյություն ունեցած լինել որպես Դանուբի ափի ձկնորսական գյուղ։", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Մոստարի անունն առաջին անգամ հիշատակվում է Դուբրովնիկի փաստաթղթում", "a599bc55"], "d": ["Մոստարի անունն առաջին անգամ հիշատակվում է 1452 թվականի ապրիլի 3-ի Դուբրովնիկի փաստաթղթում. բնակավայրը գտնվում էր Հերցեգի դքսության հողերում։ Օսմանյան նվաճումը 1466-68 թվականներն են։", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["Հյունքյար մզկիթը Սարաևոյում. բնակավայրի ամենավաղ թվագրված վկայությունը", "ad697a7d"], "d": ["Բոսնիայի սանջակբեյ Իսհաք բեյը Սարայի դաշտի առաջին մահմեդական բնակավայրում կառուցել տվեց իր համար պալատ, Ֆաթիհ Սուլթան Մեհմեդի անունով Հյունքյար մզկիթ և դրա կողքին բաղնիք։ Մզկիթը թվագրվում է հիջ. 862 (1458) թվականով. Սարաևոյի հայտնի ամենավաղ թվագրված կառույցն է։", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Իսհաք բեյի վաքֆագիրը. նվիրաբերվեց Սարաևոյի քաղաքային կորիզը", "0b364229"], "d": ["Իսհաք բեյի՝ հիջ. 866 թվականի Ջումադա ալ-ուլա (1462 թ. փետրվար) թվագրված վաքֆագրից պարզվում է, որ բացի մզկիթից և բաղնիքից կառուցվել են նաև զավիյե, մևլևիխանե, իմարեթ, կամուրջ Միլյացկայի վրա, հակառակ ափին՝ Կոլոբարա խան, բեդեստան, քարավանատուն և խանութներ։ Փաստաթուղթը քաղաքի վաքֆային հիմքն է. բնակավայրը գոյություն ուներ դրանից առաջ։", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Թաթարփազարջըղն առաջին անգամ գրանցված է ակինջիների մատյանում", "3b1c839e"], "d": ["Քաղաքի մասին ամենահին գրառումները հասնում են հիջ. 877 (1472) թվականին. Սոֆիայի ազգային գրադարանի ակինջիների մատյաններից մեկը գրանցում է բնակավայրը։", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Բանյա Լուկան առաջին անգամ հիշատակվում է թագավոր Վլադիսլավ II-ի մի հրահանգում", "0ebc6288"], "d": ["Բանյա Լուկա անունն առաջին անգամ հիշատակվում է հունգարա-խորվաթ թագավոր Վլադիսլավ II-ի 1494 թվականի փետրվարի 6-ի մի հրահանգում. շրջանը Յայցեի բանության միջոցով կապված էր Հունգարիայի թագին։ Օսմանյան նվաճումը 1527-28 թվականների ձմեռն է։", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["Բասրայի բնակիչները ավարտում են տեղափոխությունը ներկայիս տարածք. հին Բասրան լքվում է", "20f96eac"], "d": ["Բնակչությունը ժամանակի ընթացքում սկսել էր հաստատվել ներկայիս Բասրայում, որը համարում էր ավելի ապահով բեդվինների հարձակումների դեմ և որտեղ ջուրը ավելի հեշտ էր ձեռք բերել. նոր տարածք անցումն ավարտվեց հիջ. 900 (1494-95) թվականին։ Ումար խալիֆի օրոք հիմնված հին Բասրան ներկայիս քաղաքից մոտ 25 կմ հեռու էր։", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Մենգլի Գիրեյ խանը Չուրուկսուի ափին կառուցել տվեց Խանի պալատը. Բախչիսարայի հիմքը", "0792497c"], "d": ["Ոսկե Հորդայի կուսակալների և Ղրիմի առաջին խաների ամառային որսի և հանգստի վայր եղած հովտում Մենգլի Գիրեյ I խանը Չուրուկսուի ափին կառուցել տվեց այսօր Խանի պալատ անունով հայտնի պալատը և դրեց Բախչիսարայի հիմքը։ Քաղաքը, զարգանալով պալատի շուրջ և նեղ Չուրուկսուի հովտի երկայնքով, 16-րդ դարի վերջին դարձավ բարեշեն և Ղրիմի խանության կենտրոն։", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Զապորոժյան կազակները Խորտիցա կղզում հիմնեցին առաջին Սիչը", "e6ca0dd9"], "d": ["Իշխան Դմիտրո Վիշնևեցկին Դնեպրի Փոքր Խորտիցա կղզում հիմնեց առաջին Զապորոժյան Սիչը։ Ամրոցը 1558 թվականին ղրիմաթաթարների կողմից պաշարվեց և ավերվեց. Սիչը հետագայում տեղափոխվեց հարավի կղզիները։ Եզրույթ. «Սիչ» (ուկրաիներեն Sich) նշանակում է Զապորոժյան կազակների՝ Դնեպրի կղզիներում գերանակուտակով և խրամով ամրացված կենտրոնական ճամբարը. այն շտաբի, ժողովի (Ռադա) վայրի և ընտրված զորապետի (կոշևոյ) կենտրոնն է, ոչ թե պետության մայրաքաղաք։", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Հիմնվեց Բազավլուկի Սիչը", "fcd507ae"], "d": ["Այն բանից հետո, երբ թաթարները ավերեցին Տոմակիվկայի Սիչը, Զապորոժյան կազակները նոր Սիչ հիմնեցին Բազավլուկ կղզում՝ Դնեպրի Չորտոմլիկ, Պիդպիլնա և Սկարբան բազուկների միախառնման վայրում։ Սիչը 1638 թվականին, կազակական ապստամբության ճնշումից հետո, ավերվեց Լեհաստանի արշավանքով։ Եզրույթ. «Սիչ» (ուկրաիներեն Sich) նշանակում է Զապորոժյան կազակների՝ Դնեպրի կղզիներում գերանակուտակով և խրամով ամրացված կենտրոնական ճամբարը. այն շտաբի, ժողովի (Ռադա) վայրի և ընտրված զորապետի (կոշևոյ) կենտրոնն է, ոչ թե պետության մայրաքաղաք։ Այդ ժամանակ «Հեթմանությունը» դեռ գոյություն չունի (1648). Զապորոժյե անունը նշանակում է «սահանքներից այն կողմ», և Սիչերը կանգնած են Դնեպրի սահանքներից ներքև՝ տափաստանային սահմանին։ Ղազախստանի ղազախների հետ էթնիկ ազգակցություն չունեն. Զապորոժյան կազակները արևելասլավոնական (ուկրաինական), ուղղափառ համայնք են. ընդհանուր է միայն թյուրքական ծագման «կազակ» (ազատ ռազմիկ) բառը։", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["Միկիտին Ռոգի Սիչն առաջին անգամ է հիշատակվում", "61e22abc"], "d": ["Ներկայիս Նիկոպոլի տեղում՝ Միկիտին Ռոգում հիմնված չորրորդ Սիչի անունն առաջին անգամ հիշատակվում է 1628 թվականին. 1648 թվականին այն գրավեց Բոգդան Խմելնիցկին։ Սա վայրի հայտնի առաջին վկայությունն է, ոչ թե հիմնադրումը։", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Հիմնվեց Չորտոմլիկի Սիչը", "4b6e8197"], "d": ["Զապորոժյան կազակները Դնեպրի և Չորտոմլիկ գետի միախառնման հրվանդանում հիմնեցին Չորտոմլիկի Սիչը, որ կոչվում էր նաև «Հին Սիչ»։ Քանի որ աջակցել էին Մազեպային, Սիչը 1709 թվականի մայիսի 25-ին ավերվեց ռուսական բանակի կողմից։", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Խարկովը հիմնվեց կազակ վերաբնակիչների կողմից", "288b303c"], "d": ["Վայրի տափաստանի հյուսիսային եզրին, Լոպան և Խարկով գետերի միախառնման վայրում Դնեպրի աջ ափից եկած կազակ վերաբնակիչները հիմնեցին բնակավայր։ Խարկովը կարճ ժամանակում դարձավ Մոսկվային կապված Սլոբոդա Ուկրաինայի կենտրոնը։", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Զապորոժյան կազակները Ղրիմի խանի թույլտվությամբ հիմնեցին Ալեշկիի Սիչը", "ed26f29d"], "d": ["Երբ ռուսական հարձակումը ստիպեց դատարկել Կամենկայի Սիչը, Զապորոժյան կազակները Ղրիմի խանի թույլտվությամբ հաստատվեցին խանության հողերում՝ Կոնկա գետի ձախ ափի Ալեշկիում։ Պրուտի պայմանագրից հետո Գորդիենկոյի կազակները ևս միացան նրանց։ Խանը թույլ չտվեց, որ Սիչը պարիսպ և թնդանոթ ունենա։", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["Ալեշկիի Սիչը թալանվեց և լքվեց", "52361709"], "d": ["Ռուսամետ Սամարայի կազակները հարձակվեցին Ալեշկիի Սիչի վրա, թալանեցին այն և հրկիզեցին զորանոցները։ Սիչը չվերականգնվեց. կազակները 1730 թվականին վերադարձան Կամենկա և 1734 թվականին, Ռուսաստանին հավատարմության երդում տալով, հիմնեցին Նոր Սիչը։", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Վոլգայի ափին հիմնվեց Ստավրոպոլի ամրոցը", "eb087a50"], "d": ["Միջին Վոլգայում քրիստոնեությունն ընդունած կալմիկների համար հիմնվեց Ստավրոպոլի ամրոցը (ներկայիս Տոլյատին)։", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Նադիր Շահը գրավում է Ղանդահարը և ավերել տալիս հին քաղաքը", "9cc23e6b"], "d": ["Աֆշար տիրակալ Նադիր Շահը երկարատև պաշարումից հետո գրավեց Ղալզայ աֆղանների ձեռքին գտնվող Ղանդահարը։ Քաղաքը ավերվեց, և նրա բնակչությունը տեղափոխվեց հին տեղից հարավ-արևելք հիմնված Նադիրաբադ. հին Ղանդահարը այլևս երբեք քաղաք չդարձավ։", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["Ազով-Մոզդոկ գծի վրա հիմնվեց Ստավրոպոլի ամրոցը", "7fd9b9f1"], "d": ["Քյուչուք Կայնարջիից հետո Կուբանի և Թերեքի միջև տափաստանը վերահսկելու համար ստեղծված Ազով-Մոզդոկ ամրությունների գծի վրա կառուցվեց տասը ամրոց. դրանցից մեկը Ստավրոպոլն էր։ Ամրոցը հետագայում դարձավ Կովկասյան նահանգապետության և Ստավրոպոլի նահանգի կենտրոնը։", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Դնեպրի գետաբերանում հիմնվեց Խերսոնի նավաշինարանը", "115f2c34"], "d": ["Քյուչուք Կայնարջիից հետո Ռուսաստանին անցած Դնեպրի գետաբերանում, 1737 թվականին կառուցված և կարճ ժամանակում ավերված Ալեքսանդր-շանց ամրության մոտ հիմնվեց նավաշինարան և անվանվեց Խերսոն։ Քաղաքը 1784 թվականին դարձավ գավառի, 1803-ին՝ նահանգի կենտրոն։", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Ղրիմից եկած հույները Ազովի ափին հիմնեցին Մարիուպոլը", "4e3af209"], "d": ["Ղրիմից եկած հույները Կալմիուս գետի՝ Ազովի ծով թափվելու վայրում հիմնեցին Մարիուպոլը։ Քաղաքը 1784 թվականին դարձավ Եկատերինոսլավի նահանգին ենթակա գավառի կենտրոն։", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Եկատերինոսլավը տեղափոխվեց Դնեպրի ափի իր ներկայիս տեղը", "ec361381"], "d": ["Պոտյոմկինի՝ 1778 թվականին Կիլչեն և Սամարա գետերի միախառնման վայրում հիմնած Եկատերինոսլավը անառողջ դիրքի պատճառով 1783 թվականին տեղափոխվեց իր ներկայիս տեղը։", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["Ախտիարի ծովածոցում հիմնվեց ռուսական նավատորմի Սևաստոպոլ նավահանգիստը", "01058a25"], "d": ["1783 թվականին Ղրիմը Ռուսաստանին բռնակցելուց հետո ռազմական նավահանգստի համար ընտրվեց ղրիմաթաթարական Ախտիար (Աքյար) գյուղի ծովածոցը. նավահանգիստը հիմնվեց հաջորդ տարի և ստացավ Սևաստոպոլ անունը։ Քաղաքը 1804 թվականին դարձավ ռուսական Սևծովյան նավատորմի գլխավոր նավահանգիստը։", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Բուգի գետաբերանում հիմնվեց Նիկոլաևի ամրությունը", "d57e52b9"], "d": ["Հարավային Բուգ և Ինգուլ գետերի միախառնման վայրում իշխան Պոտյոմկինի հրամանով հիմնվեց ամրություն։ 1788 թվականին այստեղ բացվեց նավաշինարան, և բնակավայրը դարձավ Սևծովյան նավատորմի նավաշինության կենտրոններից մեկը։", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Մոլոչնայի ափին հիմնվեց Մելիտոպոլի կորիզ դարձած սահմանային բնակավայրը", "637d5817"], "d": ["Ղրիմի բռնակցումից հետո Մոլոչնա գետի ափին հիմնվեց սահմանային բնակավայր։ Բնակավայրը 1816 թվականին ստացավ Նովոօլեքսանդրիվկա անունը, իսկ 1841 թվականին Մելիտոպոլ անունով դարձվեց քաղաք։", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Հիմնվեց Դոնի կազակական զորքի նոր կենտրոն Նովոչերկասկը", "bf5709fd"], "d": ["Դոնի կազակական զորքի վարչական կենտրոնը մինչ այդ կենտրոն եղած Չերկասկից տեղափոխվեց Ակսայ և Տուզլով գետերի միջև՝ Բիրյուչի Կուտ վայրում հիմնված Նովոչերկասկ։", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Վադի Հալֆան գրանցվում է Բուրկհարդտի Նուբիա ճանապարհորդության մեջ", "6efc72ec"], "d": ["Շվեյցարացի ճանապարհորդ Ժ. Լ. Բուրկհարդտը 1813 թվականի մարտի 6-ի իր օրագրում գրում է, որ անցել է Վադի Հալֆայով և այնտեղ որոշ առևտուր էր արվում։ Սա գտնված առաջին թվագրված վկայությունն է։", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Ազովի ափին հիմնվեց Բերդյանսկի նավամատույցը", "908ac3cf"], "d": ["Իշխան Միխայիլ Վորոնցովի նախաձեռնությամբ Բերդա գետի՝ Ազովի ծով թափվելու վայրում հիմնվեց Բերդյանսկը։ Բնակավայրը 1835 թվականին դարձավ քաղաք, 1842-ին՝ գավառի կենտրոն։", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Մալաթիայի բնակիչները մնում են Ասպուզուի այգիներում. ժամանակակից Մալաթիայի կորիզը", "d1dba159"], "d": ["Իբրահիմ փաշայի եգիպտական բանակի դեմ օսմանյան գլխավոր շտաբը 1838 թվականի ամռանը Մեզրաայից տեղափոխվեց Մալաթիա։ Ասպուզուի ամառանոցային տներում ապրող մալաթիացիները բանակի հեռանալուց հետո չվերադարձան ավերված հին քաղաքի ձմեռային տները. Ասպուզուն դարձավ ժամանակակից Մալաթիայի կորիզը։ Հին Մալաթիան (Բաթթալղազի) փոքրանալով շարունակեց ապրել։", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Վանը հիմնվում է իր նոր տեղում. ավերված հին քաղաքը լքվում է", "6d278578"], "d": ["Վանը 1918 թվականի ապրիլի 2-ին ազատագրվեց օկուպացիայից։ Վերադարձածները, փոխանակ վերանորոգելու պատերազմի տարիներին ավերված լճափի հին Վանը, ափից մոտ 7 կմ դեպի ներս, հին Նորշեն և Արաք թաղամասերի տեղում հիմնեցին նոր քաղաք։ Հին քաղաքը լքվեց։", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Մարաշը անցավ մամլուքներին. Հալեպի նաիբ Բիլբան ալ-Թաբահին հետ վերցրեց հայերից", "03171265"], "d": ["1258 թվականից Կիլիկիայի Հայկական թագավորության ձեռքում գտնվող Մարաշը 1293 թ. սուլթան Խալիլի՝ հայերի հետ կնքած պայմանագրով կարճ ժամանակով անցել էր մամլուքներին, իսկ նրանց հեռանալուց հետո կրկին ընկել հայերի ձեռքը։ Հիջ. 697 (1298) թ. մամլուքների Հալեպի նաիբ Բիլբան ալ-Թաբահին հետ վերցրեց քաղաքը։ Այնուհետև Մարաշը, մինչև Դուլկադիրյանների վերելքը, մնաց մամլուքյան հող։", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Բյուզանդական կայսրությունը դարձավ Օսմանյան պետության խարաջատու", "615df998"], "d": ["Չիրմենի հաղթանակից (1371) հետո բյուզանդական կայսր Հովհաննես V-ը 1372 թ. ձմռանը համաձայնեց դառնալ Մուրադ I-ի խարաջատուն. վճարելու էր տարեկան խարաջ և զինվոր տրամադրելու սուլթանի արշավանքներին։ Բյուզանդիան այս ամսաթվից մինչև 1403 թ. մնաց Օսմանյան պետությանը ենթակա վասալ պետություն. Յըլդըրըմ Բայազիդի 1391 թ. շրջափակումը մեծացրեց խարաջը։ Անկարայի պարտությունից հետո Սուլեյման Չելեբիի հետ կնքված Գելիբոլուի պայմանագիրը (1403) Բյուզանդիային ազատեց խարաջից. 1424 թ. Մուրադ II-ի հետ կնքված պայմանագրով խարաջը կրկին սկսվեց։", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Յըլդըրըմ Բայազիդը Բարքուքի մահից հետո Բեսնին, Դարենդեն և Դիվրիգին միացրեց օսմանյան հողերին", "8e57d7e6"], "d": ["Մամլուք սուլթան Բարքուքի մահից (1399 թ. հունիս) հետո, երբ Մամլուքների պետության վարչական գործերը խաթարվեցին, Յըլդըրըմ Բայազիդը իջավ Եփրատի ավազան և Մալաթիայի հետ միասին Բեսնին (Բեհիսնի), Դարենդեն և Դիվրիգին միացրեց օսմանյան հողերին։ Սեբաստիան մինչ այդ, Կադի Բուրհանեդդինի 1398 թ. ամռան մահից հետո, թողնվել էր օսմանցիներին։ Դիվրիգին 1391 թվականից մամլուքյան տիրապետության տակ էր և Հալեպի նահանգին կապված առաջավոր պահակակետի դեր ուներ։ Օսմանյան կառավարումը այստեղ երկար չտևեց. մոտեցող Թեմուրի վտանգի պատճառով Դիվրիգին 1401 թ. կրկին տրվեց մամլուքներին, իսկ քաղաքի վերջնական անցումը օսմանյան կառավարման տեղի ունեցավ 1516 թ. Մարջ Դաբիկից հետո։", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Բեսնին Թեմուրի Սեբաստիայի և Մալաթիայի արշավանքի ժամանակ անցավ մամլուքներին", "4853da9a"], "d": ["Յըլդըրըմ Բայազիդի 1398 թ. Սեբաստիայի, Դարենդեի և Մալաթիայի հետ միասին վերցրած Բեսնին 1400 թ., երբ Թեմուրը վերցնում էր Սեբաստիան ու Մալաթիան, անցավ մամլուքների ձեռքը։ 1400 թ. սեպտեմբերի 27-ին Թեմուրը կատաղի պաշարումից հետո գրավեց նաև Բեսնին. այդ շրջանից նրա հեռանալուց հետո Բեսնին կրկին անցավ մամլուքյան տիրապետության տակ և, մինչև 1516 թ. օգոստոսին Յավուզ Սուլթան Սելիմի վերցնելը (բացի Դուլկադիրյան մի միջանկյալ շրջանից), մնաց մամլուքներին։", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Դիվրիգին Թեմուրի վտանգի պատճառով կրկին տրվեց մամլուքներին", "97196b1f"], "d": ["Յըլդըրըմ Բայազիդի 1398 թ. մամլուքներից վերցրած Դիվրիգին, Թեմուրի՝ Անատոլիային մոտենալու պատճառով, 1401 թ. կրկին թողնվեց մամլուքներին։ Այդ պատճառով Թեմուրի՝ Սեբաստիան ավերելուց (1400) հետո Դիվրիգին քարտեզում երևում է մամլուքյան գույնով. նույն ամիսներին Բայազիդն արևելքում վերցնում էր Երզնկան և Կամախը, այսինքն՝ մամլուքյան հողը մնաց Օսմանյան պետության արևմտյան (Սեբաստիա) և հյուսիս-արևելյան (Կամախ) հողերի միջև։ Դիվրիգին վերջնականապես օսմանցիներին անցավ միայն 1516 թ. Մարջ Դաբիկից հետո։", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Մամլուք սուլթան Շեյխը Այնթապն ու Դարենդեն հետ վերցրեց Դուլկադիրյաններից", "f90c9508"], "d": ["Դուլկադիրյանների՝ օսմանցիների հետ բարեկամությունից անհանգստացած մամլուք սուլթան Շեյխը 1414 թ. արշավանքի ելավ. նախկինում իր համաձայնությամբ Դուլկադիրյաններին տված Այնթապն ու Դարենդեն հետ վերցրեց։", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Դուլկադիրօղլու Մեհմեդ բեյը հետ վերցրեց Դարենդեն, Բեսնին էլ միացրեց իր հողերին", "df914dcb"], "d": ["Մամլուքների 1414 թ. վերցրած Դարենդեն Դուլկադիրօղլու Մեհմեդ բեյը 1418 թ. հետ վերցրեց և Բեսնին էլ միացրեց իր հողերին։", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Մամլուքները Այնթապի մոտ հաղթեցին Դուլկադիրյաններին. Բեսնին վերադարձավ մամլուքյան կառավարման (մոտավոր)", "72742430"], "d": ["Մամլուքյան բանակը 1436 թ. Այնթապի մոտ հաղթեց Դուլկադիրյաններին, Մեհմեդ բեյը քաշվեց Աքդաղ։ Բեսնիի՝ մամլուքներին վերադարձի տարին աղբյուրում գրված չէ. Բեսնին 1418 թ. միացել էր Դուլկադիրին և նախքան Շեհսուվար բեյի՝ 1465 թ. այն մամլուքներից վերցնելը վերադարձել էր մամլուքներին։ Ատլասը Բեսնին մամլուքներին վերադարձնում է հարևան կենտրոն Այնթապում կրած այս պարտության հետ միասին (հայտարարված մոտավորություն)։", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Դուլկադիրօղլու Շեհսուվար բեյը Բեսնին վերցրեց մամլուքներից (մոտավոր)", "843f0fc4"], "d": ["Ֆաթիհ սուլթան Մեհմեդի կողմից Դուլկադիրի բեյ նշանակված Շեհսուվար բեյը (1465-1472) գրավեց մամլուքների ձեռքում գտնվող Բեսնին, Գերգերը, Բիրեջիքը և Ռումկալեն. մամլուքները պարտվեցին 1467 թ. աշնանը Թուրնադաղում և 1468 թ. գարնանը Այնթապի մոտակայքում։", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Էմիր Յաշբեքը հաղթեց Շեհսուվար բեյին. Բեսնին վերադարձավ մամլուքյան կառավարման (մոտավոր)", "4d856aee"], "d": ["1471 թ. գարնանը էմիր Յաշբեքը Սավրոնի ձորում հաղթեց Շեհսուվար բեյին. մամլուքները հետ վերցրին Կադիրլին և Կոզանը։ Շեհսուվարը 1472 թ. մահապատժի ենթարկվեց Կահիրեում, մամլուքները Շահբուդաքին կրկին բերին բեյության գլուխ։ Այս վերադարձով Բեսնին էլ անցավ մամլուքյան կառավարման (TDV besni. «15-րդ դարի վերջերին կրկին անցավ մամլուքների ձեռքը»)։", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Ֆերդինանդի ուժերը գրավեցին Սոլնոկը և ամրացրին այն", "6c8416e6"], "d": ["Երբ օսմանցիները պատրաստվում էին Տիսա գետի վրա Սոլնոկում բերդ կառուցել, Ֆերդինանդ I-ի ուժերը կանխեցին նրանց. 1550 թ. սեպտեմբերի կեսին գրավեցին Սոլնոկը, և հոկտեմբերի կեսին բերդը դարձավ պաշտպանունակ։ Այսպիսով Իզաբելլայի երկրին պատկանող Սոլնոկը Տրանսիլվանիայի՝ Ֆերդինանդին անցնելուց մեկ տարի առաջ անցավ Հաբսբուրգների ձեռքը. օսմանցիները բերդը վերցրին 1552 թ.։", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Տրանսիլվանիան անցավ Հաբսբուրգյան կառավարման. Կոլոժվարի խորհրդարանը ճանաչեց Իզաբելլայի հրաժարումը", "8458a566"], "d": ["Մարտինուցիի՝ Ֆերդինանդի հետ համաձայնության պատճառով թագուհի Իզաբելլան փոքր թագավոր Յանոշ Ժիգմոնդի անունից 1551 թ. հունիսի 19-ին Սասսեբեշ ամրոցում ստորագրեց իրեն պարտադրված հրաժարականի գիրը։ Հուլիսի 26-ին Կոլոժվարում գումարված Տրանսիլվանիայի խորհրդարանը ճանաչեց այս հրաժարումը և Ֆերդինանդ թագավորի տիրապետությունը. գեներալ Կաստալդոյի հաբսբուրգյան բանակը մտավ Տրանսիլվանական Բելգրադ (Գյուլաֆեհերվար)։ Այսպիսով Օսմանյան պետությանը կապված Տրանսիլվանիան անցավ հաբսբուրգյան կառավարման, որը տևելու էր հինգ տարի։", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Տրանսիլվանիայում հաբսբուրգյան կառավարումը ավարտվեց. Տրանսիլվանիան կրկին դարձավ Օսմանյան պետությանը կապված վոյեվոդություն", "721a482a"], "d": ["Յանոշ Ժիգմոնդի փոքր տարիքի պատճառով նրան խնամակալ նշանակված ծագումով խորվաթ վանական Մարտինուցիի (Ֆրատեր Ջյորդ) ձեռքով Հաբսբուրգները 1551 թ. փորձեցին տիրել Տրանսիլվանիային. Տրանսիլվանական Բելգրադը (Գյուլաֆեհերվար), Կոլոժվարը, Բրաշովը և Սեգեշվարը հինգ տարի մնացին հաբսբուրգյան կառավարման տակ։ Օսմանցիները կանխեցին այդ վիճակը, և Տրանսիլվանիան կրկին դարձավ իրենց ենթակա խարաջատու վոյեվոդություն։ Այնուհետ Տրանսիլվանիան 16-17-րդ դարերում մոտ 150 տարի պահպանեց իր կարգավիճակը, որը հիմնված էր ներքին գործերում լայն ինքնավարության և արտաքին գործերում Ստամբուլին հավատարմության վրա։", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Վարադը, Խուստը և Տոկայը անցան Սապոյայի կողմը", "587c782d"], "d": ["1556 թ. Իզաբելլայի և Յանոշ Ժիգմոնդի՝ Տրանսիլվանիա վերադառնալուց հետո Սապոյայի կողմնակիցները 1556 թ. պաշարեցին Նագյվարադը։ 1557 թ. Վերին Տիսայի ազնվականները գրավեցին արքայական ամենակարևոր բերդերը՝ Վարադը, Խուստը և Տոկայը. Ֆերդինանդի ձեռքին մնացին միայն Դյուլան և Վիլագոշը։ Այնուհետև Վարադը դարձավ Տրանսիլվանիայի իշխանության բերդը և այդպիսին մնաց, մինչև 1660 թ. օսմանցիները վերցրին այն։", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Շվենդին վերցրեց Սաթմարը. Տրանսիլվանիայի հյուսիսային ծայրն անցավ Հաբսբուրգներին", "2256bb27"], "d": ["1561 թ. Բալաշա Մենհերտի՝ կողմը փոխելով Հաբսբուրգներին անցած Սաթմարը Բատորի Իշտվանը 1564 թ. աշնանը հարձակմամբ հետ էր վերցրել և միացրել Տրանսիլվանիային։ Հաբսբուրգյան հրամանատար Լազարուս ֆոն Շվենդին 1565 թ. փետրվարին հակագործողություն սկսեց. Տոկայը ընկավ փետրվարի 9-ին, Սերենչը՝ չորս օր անց, և Սաթմարը գրեթե առանց դիմադրության անցավ կայսերական ուժերի ձեռքը։", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Բոչկայի ուժերը վերցրին Սաթմարը", "e93b098b"], "d": ["Երբ Բոչկայի ապստամբությունը տարածվում էր հյուսիս-արևելյան Հունգարիայում, Դյուլաֆֆին 1605 թ. հունվարի 21-ին գրավեց իր պաշարած Սաթմարը։ 1606 թ. հունիսի 23-ի Վիեննայի խաղաղությունը Սաթմարի կոմիտատը ցմահ թողեց Բոչկային. քանի որ արու ժառանգ չկար, 1606 թ. դեկտեմբերի 29-ին Բոչկայի մահով կոմիտատը վերադարձավ թագավորությանը։", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Բոչկայ Իշտվանի մահը. Սաթմարի կոմիտատը վերադարձավ թագավորությանը", "3721bb9b"], "d": ["Տրանսիլվանիայի իշխան Բոչկայ Իշտվանը մահացավ 1606 թ. դեկտեմբերի 29-ին Կաշշայում։ Վիեննայի խաղաղությունը (1606 թ. հունիսի 23) Սաթմարն էլ ներառող կոմիտատները նրան ցմահ էր թողել՝ պայմանով, որ արու ժառանգ չլինելու դեպքում դրանք վերադառնան թագավորությանը. այս դրույթով Սաթմարի կոմիտատը կրկին անցավ հաբսբուրգյան հունգարական թագավորությանը։ Տրանսիլվանիան սկսեց նոր իշխան որոնել։", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Բեթլեն Գաբորը իր վերահսկողության տակ առավ Սաթմարի կոմիտատը", "80263da1"], "d": ["Բեթլեն Գաբորի 1619 թ. աշնան հունգարական արշավանքով Սաթմարի կոմիտատը անցավ Տրանսիլվանիայի իշխանի վերահսկողության տակ. 1619 թ. նոյեմբերին նա կոմիտատին նամակով էր դիմում։ 1620 թ. հունվարի 23-ի նախնական պայմանագիրը և Նիկոլսբուրգի խաղաղությունը Սաթմարն էլ ներառող յոթ կոմիտատները ցմահ թողեցին Բեթլենին։ Բեթլենի մահից (1629 թ. նոյեմբերի 15) հետո կոմիտատների վերադարձը թագավորությանը ավարտվեց 1630 թ. մարտի 30-ին։", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Բեթլեն Գաբորի յոթ կոմիտատների վերադարձը թագավորությանը ավարտվեց", "31b5968f"], "d": ["Նիկոլսբուրգի խաղաղությունը Սաթմարն էլ ներառող Վերին Հունգարիայի յոթ կոմիտատները ցմահ էր թողել Բեթլեն Գաբորին։ Բեթլենի 1629 թ. նոյեմբերի 15-ի մահից հետո կոմիտատների վերադարձը թագավորությանը սկսվեց 1629 թ. նոյեմբերի 30-ի հրահանգով և ավարտվեց 1630 թ. մարտի 30-ին։", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["Ռակոցի Դյորդ I-ը ստացավ Սաթմարը", "f398635b"], "d": ["Տրանսիլվանիայի իշխան Ռակոցի Դյորդ I-ի 1644 թ. արշավանքում Սաթմարի գերմանական կայազորը անցավ Ռակոցիի ծառայության, և բերդը անցավ Տրանսիլվանիայի ձեռքը։ 1645 թ. դեկտեմբերի 16-ի Լինցի խաղաղությունը բերդը թողեց Ռակոցիի ժառանգներին, քանի դեռ Տրանսիլվանիայի գահին Ռակոցի կլինի։", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Նիտրայի կորուստը. Դե Սուշը հետ վերցրեց բերդը", "c71bf012"], "d": ["1663 թ. Նովե Զամկիի (Ույվար) գրավումից հետո կարճ դիմադրությամբ հանձնված Նիտրան կայսերական հրամանատար Դե Սուշը պաշարեց 1664 թ. ապրիլի 15-ին. բերդը հանձնվեց 1664 թ. մայիսի 3-ին։ Քանի որ Վաշվարի պայմանագիրը գրավված վայրերը թողնում էր այն վիճակում, ինչ վիճակում գտնվում էին, Նովե Զամկին մնաց Օսմանյան պետությանը, իսկ Նիտրան՝ Հաբսբուրգների ձեռքին։", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Լևայի կորուստը", "f311920e"], "d": ["Նիտրայից հետո Դե Սուշը 1664 թ. հունիսի 9-ին պաշարեց Լևան. հունիսի 13-ին ստորագրվեց կապիտուլյացիան, և հունիսի 14-ին բերդը կայսերական ուժերի ձեռքին էր։ 1664 թ. հուլիսի 19-ի Լևայի (Գարամսենտբենեդեկ) ճակատամարտը պատկանելությունը չփոխեց. այն ավարտվեց նրանով, որ Հաբսբուրգները պահեցին Լևան և Նիտրան։", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Դորոշենկոն Չիհիրինը հանձնեց Սամոյլովիչին", "3b538237"], "d": ["Օսմանյան հովանու ներքո գտնվող Աջափնյա հեթման Պետրո Դորոշենկոն 1676 թ. սեպտեմբերի 19-ին իր մայրաքաղաք Չիհիրինը հանձնեց Ձախափնյա հեթման Սամոյլովիչին և ռուսական ուժերին։ Օսմանցիները Դորոշենկոյին պաշտոնանկ արին և նրա փոխարեն բերեցին Յուրի Խմելնիցկիին. Չիհիրինի ռուսական կայազորին դուրս մղելու համար 1677 թ. պաշարումը ձախողվեց, բերդը վերցվեց միայն 1678 թ. օգոստոսի 21-ին։", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Էրդելի Բանատի ամրոցների (Թեմեշվար, Լիպպա, Լուգոշ, Կարանշեբեշ) հանձնումը Հունգարիայի թագավոր Ֆերդինանդին", "0e354976"], "d": ["1551 թվականին գեներալ Կաստալդոյի հրամանատարությամբ Հաբսբուրգյան բանակը մտավ Էրդել. թագուհի Իզաբելլան և նրա որդին ստիպված եղան հրաժարվել Հունգարիայի գահի նկատմամբ իրենց իրավունքներից։ Մարտինուցին Կաստալդոյի հավանությամբ 1551 թվականի հուլիսի կեսին ուղարկեց Բատորի Էնդրեին, որպեսզի Թեմեշվար, Լիպպա, Շոյմոշ, Կարանշեբեշ, Լուգոշ, Բեչե, Բեչկերեկ և Չանադ ամրոցները ընդունի Ֆերդինանդի անունից։ Այսպիսով օսմանյան հովանու տակ գտնվող Էրդելի հարավային ամրոցներն անցան Հաբսբուրգների ձեռքը. Կանունի Սուլեյմանի 1551-1552 թվականների արշավանքները դրա պատասխանն են։", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Պետրովիչ Պետերի նշանակումը Լուգոշի և Կարանշեբեշի սանջակբեյ", "bcbe73e4"], "d": ["Իզաբելլայի և Պետրովիչի համառ խնդրանքով Կանունի Սուլեյմանը որոշեց փոքրիկ Յանոշ Զիգմոնդին վերադարձնել Էրդել։ 1554 թվականի ապրիլի 7-ին Հալեպից գրած նամակով նա էրդելցիներին հրամայեց երեխային վերադարձնել իր երկիր, իսկ Վալախիայի և Մոլդովայի վոյևոդներին պատվիրեց այդ գործում օգնել Պետրովիչին, որին նույն ժամանակ նշանակեց Լուգոշի և Կարանշեբեշի սանջակբեյ։ Այսպիսով 1552 թվականին գրավված Լուգոշը որպես օսմանյան սանջակ տրվեց Պետրովիչին։", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Լիպպայի պաշարման վերացումը. Լուգոշի բանի հարձակումը Թեմեշվարի վրա", "be03430e"], "d": ["1596 թվականի գարնանը Թեմեշվարի փաշան պաշարեց Լիպպան։ Մայիսի 10-ից 11-ը գիշերը, Էրդելի Լուգոշի բան Պալատիչ Դյորդի հրամանով, Բուդայ Դյորդի զինվորները հարձակվեցին Թեմեշվարի արվարձանների վրա և հրկիզեցին դրանք. ամրոցում Բորբեյ Դյորդի՝ բոլոր թնդանոթները կրակելու հրամանը նույնպես փաշային համոզեց, որ օգնություն է եկել։ Փաշան մայիսի 11-ին, հեռանալով Լիպպայի մոտից, շտապեց պաշտպանել իր կենտրոնը։ Լուգոշն այդ ժամանակ Էրդելի իշխանապետության ձեռքին էր։", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Օրշովայի գրավումը Վետերանիի հրամանատարությամբ ավստրիական ուժերի կողմից", "1b4a4f6c"], "d": ["1688 թվականի արշավանքում գեներալ Վետերանին, Կարանշեբեշը գրավելուց հետո, շարժվեց Օրշովայի վրա և գրավեց նաև այն։ Աղբյուրում գրավման օրը չկա. օգտագործվել է տարվա հիմնական ամսաթիվը՝ 1688 թվականի հունվարի 1-ը։", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Օրշովայի վերագրավումը Թյոքյոլիի և օսմանյան ուժերի կողմից", "c5645da9"], "d": ["1688 թվականին Վետերանիի գրաված Օրշովայի վրա Վետիսլանի գրավումից հետո շարժվեցին Թյոքյոլին և օսմանյան փաշաները։ Աննշան բախումներից հետո Թյոքյոլին 1689 թվականի հուլիսի 15-ին մտավ Օրշովա։ Վտանգի լուրով եկած Հեյսլերը, տեսնելով, որ հակառակ ուժը լավ հագեցած է ռազմամթերքով և նավերով, նահանջեց Էրդելը պաշտպանելու համար։ Օգոստոսին Էրբևիլի հարձակումը քաղաքի առաջ նույնպես չկարողացավ հետ վերցնել Օրշովան։", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Լուգոշի սանջակն անցավ Հաբսբուրգյան օկուպացիայի տակ (1691-1695)", "c8bcd6bd"], "d": ["Լուգոշի սանջակը 1691-1695 թվականներին մնաց Հաբսբուրգյան (գերմանական) օկուպացիայի տակ. Մուստաֆա II-ը 1695 թվականի սեպտեմբերի 22-ին վերանվաճեց այն։ Հին գրառման մեջ 1689-1695 թվականները հայտարարված բացթողում էին. 1691-1695 հատվածն այժմ ներկվում է որպես Հաբսբուրգյան, իսկ 1689-1691-ը մնում է բացթողում։ Ամսաթիվը վերցված է միայն տարով։", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Լուգոշի ամրոցն անցավ Հաբսբուրգյան կառավարման տակ", "6a9d401f"], "d": ["Թեմեշվարի էյալեթին ենթակա Լուգոժ սանջակային ամրոցը 1695 թվականից օսմանյան ձեռքին էր. 1716 թվականի պաշարման վերջում էյալեթի կենտրոնի հանձնումով այն թողնվեց Հաբսբուրգյան միապետությանը։ Հին գրառումը փոխանցումը դնում էր տարվա հիմնական ամսաթվի՝ 1716 թվականի հունվարի 1-ի վրա։", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Օրշովայի գրավումը Հաբսբուրգյան բանակի կողմից (1717 թվականի արշավանք)", "7a4faffe"], "d": ["1717 թվականի արշավանքում գեներալ Սպլենյին օգոստոսի 27-ին հասավ Օրշովա և հեշտությամբ գրավեց քաղաքը. այսպիսով Օրշովան, որ 1716-ին Մերսին չէր կարողացել գրավել, անցավ Հաբսբուրգների ձեռքը։ Շրջակա դանուբյան ափի բջիջները (ներառյալ սերբական ափի Ջերդապի հատվածը), քանի որ կապված են ամենամոտ բնակավայրային կետի՝ Օրշովայի հետ, ներկվում են նրա տիրոջ գույնով։ Ամսաթիվը վերցված է միայն տարով. ճշգրիտ օրը հաստատված չէ։", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Օրշովայի պալանկայի անցումը Օսմանյան պետությանը. կայազորի նահանջը Ադակալե", "de759b16"], "d": ["1738 թվականի արշավանքի սկզբում Վիդինի մուհաֆիզ Հաջի Մեհմեդ փաշան հարձակվեց Դանուբի ափին գտնվող Erzsébet ամրաշինության վրա։ Մայիսի 8-ի կեսօրից հետո 4-5 հազար սիփահիներից բաղկացած ջոկատը Դանուբի ձախ ափով շարժվեց դեպի Օրշովա և հարձակվեց Օրշովայի պալանկայի վրա. մոտ հարյուր զոհ տված ավստրիական կայազորը նահանջեց Նոր Օրշովա, այսինքն՝ Ադակալե կղզի-ամրոցը։ Հուլիսի Մեհադիայի բախումներից հետո Ադակալեն ևս 1738 թվականի օգոստոսին անցավ օսմանյան ձեռքը. 1739 թվականի Բելգրադի պայմանագիրը ճանաչեց այս վիճակը։", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Մուրադ II-ը գրավեց Կրուշևացը, Նիշն ու Պիրոտը վերադարձան Օսմանյան պետությանը", "54af926a"], "d": ["Սերբ դեսպոտ Ստեֆան Լազարևիչի անժառանգ մահից (1427) հետո Մուրադ II-ը, հենվելով Բայազիդ I Յըլդըրըմի՝ սերբ արքայադստեր հետ ամուսնության վրա և հայտարարելով, որ ինքը Սերբիայի օրինական ժառանգորդն է, գործի անցավ և գրավեց Կրուշևացը (1428)։ Նույն տարում, Լազարևիչի մահից հետո, օսմանցիները հետ վերցրին նաև Պիրոտի ամրոցը. քաղաքը 1412 թվականին գրավել էր Ստեֆանը և պաշտպանել Մուսա Չելեբիի դեմ։ TDV-ի «nis» հոդվածի համաձայն՝ օսմանցիները նույն տարում (հիջ. 831/1428) հետ վերցրին նաև Նիշը։ Այսպիսով Մեծ Մորավայի և Նիշավայի հովիտները կապող գիծն անցավ օսմանյան վերահսկողության տակ։", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Խաչակիրների բանակը գրավեց Պիրոտը. «Երկար արշավանքի» Նիշավայի թևը", "fdf6140c"], "d": ["Թագավոր Վլադիսլավի և սերբ դեսպոտ Գեորգ Բրանկովիչի գլխավորած խաչակրաց բանակը 1443 թվականին գրավեց Պիրոտը։ Նույն արշավանքի շարունակությամբ օսմանյան ուժերը նոյեմբերին ջախջախվելու էին Իզլադիի լեռնանցքում։ Պիրոտը Սեգեդի պայմանագրից (1444) հետո Մուրադ II-ի կողմից կրկին տրվեց սերբերին, բայց 1456 թվականին, Գեորգ Բրանկովիչի մահից հետո, անցավ օսմանցիներին։", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Կրուշևացի շրջանում հաստատվեց վերջնական օսմանյան տիրապետությունը", "9715382a"], "d": ["1444 թվականին հունգար պատվիրակների հետ կնքված պայմանագրի արդյունքում Բրանկովիչին թողնված Կրուշևացը Վառնայի հաղթանակին հաջորդած տարիներին կրկին անցավ թուրքական տիրապետության տակ։ Քաղաքի այս երկրորդ նվաճումը վավերագրված է ոչ թե պատերազմի, այլ ֆինանսական գրառումով. Կրուշևացին ենթակա որոշ գյուղերի թիմարային գրառումները թվագրվում են 1453-ի վերջ / 1454-ի սկիզբ. բայց դա միայն գյուղերի վկայություն է. 1454 թվականին օսմանյան ուժերը ջախջախվեցին Կրուշևացի մոտ, իսկ 1455-ին Կրուշևացը որպես սահման թողնվեց Բրանկովիչին։ Ըստ TDV-ի՝ շրջանում վերջնական օսմանյան տիրապետությունը հաստատվեց 1458 թվականին։", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Մորեայի դեսպոտության հիմնադրումը. Մանուել Կանտակուզենոսը Միստրասում", "87660b82"], "d": ["Բյուզանդական կայսր Հովհաննես Կանտակուզենոսը իր որդի Մանուելին Մորեայում տվեց առանձին կառավարման շրջան. այսպես ծնվեց Միստրաս կենտրոնով Մորեայի դեսպոտությունը։ Մանուելը կառավարեց մինչև 1380 թվականը. այդ շրջանում բյուզանդական մշակույթն ու արվեստը հատկապես զարգացան Միստրասում։ Դեսպոտությունը տևեց մինչև 1460 թվականը՝ Ֆաթիհի նվաճումը։", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Դեսպոտ Կոնստանտինը Պատրասը խլեց ֆրանկներից", "cb0dd18c"], "d": ["Մորեայի դեսպոտ Կոնստանտինը (1449-ին՝ Բյուզանդիայի վերջին կայսրը) Պատրասը հետ վերցրեց լատիններից. այսպիսով թերակղզու հյուսիս-արևմուտքի այս կարևոր նավահանգիստը ևս միացավ դեսպոտությանը։ Պատրասը 1458 թվականին, Ֆաթիհի Մորեայի արշավանքի ժամանակ, անցավ օսմանյան տիրապետության տակ։", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Ստեպան Վուկչիչ-Կոսաչան՝ «Սուրբ Սավայի դուքս». Հերցեգովինայի ծնունդը", "cc67061f"], "d": ["Հումը և Տրեբինյեն մեկ բեյության մեջ միավորած Ստեպան Վուկչիչ-Կոսաչան ապստամբեց Բոսնիայի թագավորի դեմ և իրեն հռչակեց «Սուրբ Սավայի հերցոգ (դուքս)». տիտղոսը նրան 1448 թվականին տվեց կայսր Ֆրիդրիխ III-ը։ Հերցեգովինա («Հերցոգի երկիրը») անունը ծագում է այս տիտղոսից։ Հերցեգովինան 1466 թվականից սկսած մաս-մաս անցավ Օսմանյան պետությանը, 1470 թվականին դարձավ սանջակ, իսկ մնացած հողերը միացան 1482 թվականի սկզբին։", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Կրակովի հաշտությունը. Տևտոնական օրդենի պետությունը վերածվեց Պրուսիայի դքսության", "78666ddd"], "d": ["Տևտոնական ասպետների մեծ մագիստրոս Ալբրեխտ Բրանդենբուրգցին, Լեհաստանի դեմ օգնություն չգտնելով, ստորագրեց Կրակովի հաշտությունը։ Օրդենի պետությունը (Ordensstaat) դարձավ Լեհաստանի գերիշխանության տակ գտնվող, Բրանդենբուրգյան հարստությանն անցած ժառանգական և աշխարհիկ դքսություն։ Կենտրոնը Քյոնիգսբերգն էր. Ալբրեխտը 1544 թվականին այստեղ հիմնեց Ալբերտինա համալսարանը։ Դքսությունը 1701 թվականին վերածվեց Պրուսիայի թագավորության։", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Ավստրիայի Հանրապետության հռչակումը. Հաբսբուրգյան միապետության վախճանը", "c84f316c"], "d": ["Կայսր Կարլ I-ի՝ նոյեմբերի 11-ին պետական գործերից հեռանալու հաջորդ օրը Ժամանակավոր ազգային ժողովն ընդունեց պետության և կառավարման ձևի մասին օրենքը, և հռչակվեց հանրապետությունը։ Հաբսբուրգյան Ավստրիայի տեղը գրավեց Վիեննա կենտրոնով Առաջին հանրապետությունը։ Այս հռչակմամբ Վիեննան, Լինցը, Զալցբուրգը, Ինսբրուկը, Կլագենֆուրտը, Բրեգենցը և գերմանա-ավստրիական մյուս քաղաքները դարձան Ավստրիայի Հանրապետության (Deutschösterreich) հողը։", "2dcc1399"]},
"OLAYLAR_T5_1000A:1008-01-01:0":{"b": ["Բաթումը Վրաց թագավորության/թագավորությունների տիրապետության ներքո — աղբյուրի թվագրված վկայությունը", "62cd2833"], "d": ["Աղբյուրը Բաթում քաղաքը այս թվականին ցույց է տալիս Վրաց թագավորության/թագավորությունների վարչության ներքո. ավելի վաղ տիրապետությունը աղբյուրում թվագրված չէ (ատլասը այս թվականից առաջվա շրջանը թողնում է դատարկ)։", "e03655c9"]},
"OLAYLAR_T5_1000A:1024-01-01:0":{"b": ["Մրվանյան Նասր ալ-Դաուլան Ամիդը միացրեց իր ամիրայությանը", "9fbc8c85"], "d": ["Մրվանյան ամիրա Նասր ալ-Դաուլա Ահմեդը Ամիդը (Դիարբեքիր) միացրեց ամիրայության հողերին. հաջորդ տարի վերցրեց նաև Ուրֆան։", "d585a28b"]},
"OLAYLAR_T5_1000A:1054-01-01:0":{"b": ["Մարաղան անցավ սելջուկյան տիրապետության տակ", "c011cac9"], "d": ["Ռավվադյանների ձեռքին գտնվող Մարաղան Տուղրիլ բեյի Ատրպատականի արշավանքով անցավ սելջուկյան տիրապետության տակ։", "2ff74d2d"]},
"OLAYLAR_T5_1000A:1055-12-18:0":{"b": ["Տուղրիլ բեյը մտավ Բաղդադ", "38af55c2"], "d": ["Խալիֆա ալ-Կաիմ Բի-ամր Ալլահի հրավերով Բաղդադ եկած Տուղրիլ բեյը վերջ դրեց Բուվեյհյանների տիրապետությանը։", "f7f905d1"]},
"OLAYLAR_T5_1000A:1056-01-01:0":{"b": ["Մոսուլն անցավ սելջուկների ձեռքը", "20b8da93"], "d": ["Մոսուլը Իրաքի հետ միասին անցավ սելջուկներին. Բասասիրիի կարճատև գրավումին չնայած՝ չորս տարի մնաց սելջուկների ձեռքին։", "a55cff1d"]},
"OLAYLAR_T5_1000A:1061-01-01:0":{"b": ["Մոսուլը կրկին Ուկայլյանների ձեռքին", "8b7c0603"], "d": ["Մոսուլը 1061 թ. կրկին անցավ Ուկայլյան տիրապետության տակ. 1084 թ. սելջուկյան գրավումից հետո էլ Մելիքշահը քաղաքը վերադարձրեց Ուկայլյան ամիրային։", "71824a2b"]},
"OLAYLAR_T5_1000A:1064-01-01:0":{"b": ["Ալփ Արսլանը վերջ դրեց Նախիջևանի շահությանը", "5620360e"], "d": ["Ռավվադյաններին հաղթած Ալփ Արսլանը վերացրեց Դուլաֆյանների հիմնած Նախիջևանի շահությունը։", "f9fd7d73"]},
"OLAYLAR_T5_1000A:1071-01-01:0":{"b": ["Էմիր Սալթուկը գրավեց Էրզրումը", "f52c09dd"], "d": ["Մանազկերտից հետո Ալփ Արսլանը Էրզրումի շրջակայքը որպես իքտա տվեց էմիր Սալթուկին. Սալթուկը նույն տարում վերցրեց քաղաքը, և հիմնվեց Սալթուկյանների բեյությունը (ըստ Յընանչի՝ 1080)։", "505fcc25"]},
"OLAYLAR_T5_1000A:1071-01-01:1":{"b": ["Դանիշմենդ Ղազին գրավեց Սեբաստիան", "348d7ad3"], "d": ["Մանազկերտից հետո իրեն որպես իքտա տրված Սեբաստիան վերցրած Դանիշմենդ Ղազին այստեղ հիմնեց հարստության միջուկը (գրավման թվականը վիճելի է. կա նաև 1080-ի վարկածը)։", "b9b5dd65"]},
"OLAYLAR_T5_1000A:1074-01-01:0":{"b": ["Փիլարտոսը գրավեց Մալաթիան", "9c80e3bd"], "d": ["Կիլիկիայում հայկական իշխանություն հիմնած Փիլարտոսը, ներկայանալով որպես Բյուզանդիայի ներկայացուցիչ, վերցրեց Մալաթիան և կառավարեց կուսակալների (Գաբրիել և այլք) միջոցով։", "958ede64"]},
"OLAYLAR_T5_1000A:1074-01-01:1":{"b": ["Էմիր Դանիշմենդը գրավեց Թոքաթը", "c9321fb6"], "d": ["Մանազկերտի հաղթանակից հետո էմիր Դանիշմենդը Թոքաթը վերցրեց Բյուզանդիայից։", "dcc7f8e2"]},
"OLAYLAR_T5_1000A:1085-01-01:0":{"b": ["Սելջուկները Հասանքեյֆը վերցրին Մրվանյաններից", "4fa9d559"], "d": ["Մելիքշահի օրոք սելջուկները, վերջ դնելով Մրվանյան տիրապետությանը, վերցրին նաև Հասանքեյֆը։", "b9794646"]},
"OLAYLAR_T5_1000A:1085-05-31:0":{"b": ["Ֆախր ալ-Դաուլայի որդին վերցրեց Ամիդը, Մրվանյան տիրապետությունն ավարտվեց", "ecaf6b03"], "d": ["Մելիքշահի կողմից նշանակված Ֆախր ալ-Դաուլա Իբն Ջահիրի որդի Զաիմ ալ-Ռուասան Ամիդը վերցրեց Մրվանյաններից։", "8745ce9d"]},
"OLAYLAR_T5_1000A:1093-01-01:0":{"b": ["Թութուշը գրավեց Դիարբեքիրը", "469b8ebc"], "d": ["Մելիքշահի մահից հետո սուլթանական գահին հավակնող Թութուշը վերցրեց Դիարբեքիրի շրջանը և գերի վերցրեց վերջին Մրվանյան ամիրա Մանսուրին։", "52daa285"]},
"OLAYLAR_T5_1000A:1095-01-01:0":{"b": ["Թուրքմեն բեյ Սադրը սկսեց իշխել Ամիդում", "3d67b786"], "d": ["Թութուշի մահից հետո Ամիդին տիրեց թուրքմեն բեյ Սադրը. նրան հաջորդած Ինալը հիմնեց Ինալօղուլների հարստությունը։", "5fdca35c"]},
"OLAYLAR_T5_1000A:1096-01-01:0":{"b": ["Քյուրբողան գրավեց Մոսուլը", "462a238f"], "d": ["Սելջուկյան էմիր Քյուրբողան Մոսուլը վերցրեց Ուկայլյաններից։ (Զու-լ-կաադա 489 / 1096 թ. նոյեմբեր. ատլասը, հետևելով քարտին, գրում է տարվա ճշգրտությամբ։)", "14d9ca6d"]},
"OLAYLAR_T5_1000A:1100-01-01:0":{"b": ["Նիքսարը Դանիշմենդյանների տիրապետության ներքո — աղբյուրի թվագրված վկայությունը", "81181870"], "d": ["Աղբյուրը Նիքսար քաղաքը այս թվականին ցույց է տալիս Դանիշմենդյանների վարչության ներքո. ավելի վաղ տիրապետությունը աղբյուրում թվագրված չէ (ատլասը այս թվականից առաջվա շրջանը թողնում է դատարկ)։", "c1463e88"]},
"OLAYLAR_T5_1000A:1102-09-18:0":{"b": ["Դանիշմենդյան Գյումյուշթեգին Ղազին վերցրեց Մալաթիան", "87f1166c"], "d": ["Գյումյուշթեգին Ղազին պաշարման ավարտին գրավեց Մալաթիան։", "2d0e9668"]},
"OLAYLAR_T5_1000A:1106-09-02:0":{"b": ["Քըլըչ Արսլան I-ը ընդունեց Մալաթիայի հանձնումը", "eca366d5"], "d": ["Գյումյուշթեգինի մահից հետո Քըլըչ Արսլան I-ը երկու ամսից ավելի տևած պաշարումով Մալաթիան միացրեց սելջուկյան հողերին։", "69bdbc2c"]},
"OLAYLAR_T5_1000A:1108-03-04:0":{"b": ["Մազյադյան Սադական մահացավ Նուամանիայում, Հիլլան՝ սելջուկներին", "e5ecea7c"], "d": ["Մուհամմեդ Տապարը հաղթեց Սադակային. նրա որդի Դուբեյսը գերի ընկավ, և նրան թույլ չտրվեց վերադառնալ Հիլլա։", "be1e2910"]},
"OLAYLAR_T5_1000A:1111-01-01:0":{"b": ["Իլարսլանը Էլբիսթանը ետ վերցրեց Տանկրեդից", "923962c2"], "d": ["Անտիոքի իշխան Տանկրեդի վերցրած Էլբիսթանը ետ վերցրեց Մալաթիայի մելիք Տուղրուլ Արսլանի աթաբեկ Իլարսլանը։", "ce0754bd"]},
"OLAYLAR_T5_1000A:1112-01-01:0":{"b": ["Արթուկյան Բալաքը տիրեց Խարբերդին", "83425a6e"], "d": ["Արթուկ բեյի թոռ Բալաք բ. Բահրամը, տիրելով Խարբերդին, հիմնեց Բալուն կենտրոն ունեցող իր բեյությունը։", "ff838897"]},
"OLAYLAR_T5_1000A:1116-01-01:0":{"b": ["Նիղդեն Անատոլիայի (Թուրքիայի) Սելջուկյան պետության տիրապետության ներքո — աղբյուրի թվագրված վկայությունը", "dfb24c4b"], "d": ["Աղբյուրը Նիղդե քաղաքը այս թվականին ցույց է տալիս Անատոլիայի (Թուրքիայի) Սելջուկյան պետության վարչության ներքո. ավելի վաղ տիրապետությունը աղբյուրում թվագրված չէ (ատլասը այս թվականից առաջվա շրջանը թողնում է դատարկ)։", "477146f3"]},
"OLAYLAR_T5_1000A:1117-01-01:0":{"b": ["Դուբեյսը վերադարձավ Հիլլա", "9bc0e03a"], "d": ["Մուհամմեդ Տապարի մահից հետո Դուբեյսը Իրաքի սելջուկ սուլթան Մահմուդի օրոք կարողացավ գնալ Հիլլա։", "d9aec87c"]},
"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["Մահմուդը Բաղդադում հռչակվեց Իրաքի սելջուկ սուլթան — հիմնվեց Իրաքի Սելջուկյան պետությունը", "18babf94"], "d": ["Մուհամմեդ Տապարի մահից հետո նրա որդի Մահմուդը խալիֆայի կողմից հռչակվեց սուլթան. հիմնվեց Իրաքի Սելջուկյան պետությունը։ Բաղդադը, Մոսուլը և Թիքրիթը մնացին Իրաքի սելջուկյան սուլթանությանը ենթակա, Ատրպատականը (Մարաղա, Նախիջևան) նույնպես բաժին ընկավ Իրաքի սելջուկներին։ Թիքրիթը աղբյուրում այս տարի հիշատակվում է որպես Բաղդադի շահնայի իքտա։", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["Հովհաննես II Կոմնենոսը ետ վերցրեց Դենիզլին", "cb523c0f"], "d": ["Բյուզանդիայի կայսր Հովհաննես II Կոմնենոսը ստիպեց Լաոդիկեայի սելջուկ հրամանատար Ալփ Կարային նահանջել. Դենիզլիի հողերը կրկին անցան Բյուզանդիային («bizans» հոդվածը նշում է 1120)։", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["Ակսունկուր ալ-Ահմադիլին ուղարկվեց Մարաղա", "7a3d6deb"], "d": ["Սուլթան Մահմուդը Ակսունկուր ալ-Ահմադիլիին ուղարկեց Մարաղա. Ահմադիլյան աթաբեկությունը հաստատվեց քաղաքում։", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-12-10:0":{"b": ["Դանիշմենդյան Էմիր Ղազին ընդունեց Մալաթիայի հանձնումը. Էլբիսթանը նույնպես անցավ Դանիշմենդյաններին", "97f3f958"], "d": ["Բալաքի մահից հետո Էմիր Ղազին երկարատև պաշարումով Մալաթիան վերցրեց սելջուկյան մելիք Տուղրուլ Արսլանից. Մալաթիայի շրջանի գրավմամբ Էլբիսթանը նույնպես անցավ Դանիշմենդյան վարչության տակ։", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["Էմիր Ղազին Անկարան վերցրեց սելջուկներից", "25b745cd"], "d": ["Դանիշմենդյան Էմիր Ղազին, հաղթելով Քըլըչ Արսլան I-ի որդի Մելիք Արաբին, Անկարան վերցրեց նրանից։", "008f5e3f"]},
"OLAYLAR_T5_1000A:1127-01-01:1":{"b": ["Իմադ ալ-Դին Զանգին՝ Մոսուլի աթաբեկ (Զանգյաններ)", "ba79276b"], "d": ["Իրաքի սելջուկ սուլթան Մահմուդը Մոսուլը որպես իքտա տվեց Իմադ ալ-Դին Զանգիին. հիմնվեց Մոսուլի աթաբեկությունը։", "a1929772"]},
"OLAYLAR_T5_1000A:1134-01-01:0":{"b": ["Կեսարիան Դանիշմենդյանների տիրապետության ներքո — աղբյուրի թվագրված վկայությունը", "3b9b8604"], "d": ["Աղբյուրը Կեսարիա քաղաքը այս թվականին ցույց է տալիս Դանիշմենդյանների վարչության ներքո. ավելի վաղ տիրապետությունը աղբյուրում թվագրված չէ (ատլասը այս թվականից առաջվա շրջանը թողնում է դատարկ)։", "e82b707e"]},
"OLAYLAR_T5_1000A:1142-01-01:0":{"b": ["Կամախը Մենգուջեքյանների (Մենգուջեքօղուլներ) տիրապետության ներքո — աղբյուրի թվագրված վկայությունը", "d86927c6"], "d": ["Աղբյուրը Կամախ քաղաքը այս թվականին ցույց է տալիս Մենգուջեքյանների (Մենգուջեքօղուլներ) վարչության ներքո. ավելի վաղ տիրապետությունը աղբյուրում թվագրված չէ (ատլասը այս թվականից առաջվա շրջանը թողնում է դատարկ)։", "fcb6186c"]},
"OLAYLAR_T5_1000A:1144-01-01:0":{"b": ["Սուլթան Մասուդը վերցրեց Էլբիսթանը", "825e2c56"], "d": ["Մասուդ I-ը Այն ալ-Դաուլայի ձեռքին գտնվող Էլբիսթանն ու Ջեյհանը գրավեց և իր որդի Քըլըչ Արսլանին նշանակեց մելիք։", "d69cdacb"]},
"OLAYLAR_T5_1000A:1148-01-01:0":{"b": ["Նախիջևանը միացավ Իլդեգիզյաններին", "774400cc"], "d": ["Սելջուկների տրոհմամբ Նախիջևանը միացավ Իլդեգիզյանների պետությանը և մինչև 1174 թվականը եղավ նրանց կենտրոնը (միանալու տարին նշված չէ. հարստության սկիզբն է)։", "bf42d3bd"]},
"OLAYLAR_T5_1000A:1149-01-01:0":{"b": ["Թիքրիթը անցավ Բեգթեգինյաններին (EI2)", "a2caf5af"], "d": ["TDV-ի՝ EI2-ից փոխանցածի համաձայն Թիքրիթը 1149-1190 թվականներին գտնվում էր Բեգթեգինյանների տիրապետության ներքո։", "d10d23e8"]},
"OLAYLAR_T5_1000A:1150-04-30:0":{"b": ["Սուլթան Մասուդը Հիլլան տվեց Սալարքերդին", "4bdbd034"], "d": ["Մազյադյան Ալիի մահից հետո սուլթան Մասուդը Հիլլան տվեց իր հրամանատար Սալարքերդին։", "059e9aeb"]},
"OLAYLAR_T5_1000A:1152-04-08:0":{"b": ["Սուլթան Մասուդը մահացավ. խալիֆա Մուկթաֆին դարձավ Իրաքի միակ տիրակալը, վերցրեց Հիլլան, Կուֆան և Վասիտը", "21192405"], "d": ["Սուլթան Մասուդի մահով խալիֆա ալ-Մուկթաֆի Լի-ամր Ալլահը Բաղդադում և Իրաքում հաստատեց սելջուկյան ազդեցությունից անկախ տիրապետություն. խալիֆայի վեզիրը գրավեց Հիլլան, գրավվեցին նաև Կուֆան և Վասիտը։", "cd348b82"]},
"OLAYLAR_T5_1000A:1156-01-01:0":{"b": ["Յաղըբասանը գրավեց Էլբիսթանը", "824708d3"], "d": ["Մասուդի մահից հետո Սեբաստիայի Դանիշմենդյան մելիք Յաղըբասանը վերցրեց Էլբիսթանը. համաձայնությամբ դրա կառավարումը թողնվեց նրան։", "d413e508"]},
"OLAYLAR_T5_1000A:1156-01-01:1":{"b": ["Սելջուկյան հրամանատարները վերցրին Հիլլան, Մազյադյանները՝ նաիբին ենթակա", "43afd955"], "d": ["Հիլլան վերցրին սուլթան Մուհամմեդ բ. Մահմուդի հրամանատարները. Մազյադյանները իշխեցին որպես սուլթանի նաիբին ենթակա։", "c6c81147"]},
"OLAYLAR_T5_1000A:1160-01-01:0":{"b": ["Բաքուն Շիրվանշահերի տիրապետության ներքո — աղբյուրի թվագրված վկայությունը", "1f2863e4"], "d": ["Աղբյուրը Բաքու քաղաքը այս թվականին ցույց է տալիս Շիրվանշահերի վարչության ներքո. ավելի վաղ տիրապետությունը աղբյուրում թվագրված չէ (ատլասը այս թվականից առաջվա շրջանը թողնում է դատարկ)։", "506dae86"]},
"OLAYLAR_T5_1000A:1163-01-01:0":{"b": ["Խալիֆա Մուստանջիդը վերցրեց Հիլլան, Մազյադյանները վերացան", "4348923c"], "d": ["Խալիֆա Մուստանջիդի և Բանի Մունթաֆիքի ջոկատները գրավեցին Հիլլան, Մազյադյանները ցրվեցին։", "da071466"]},
"OLAYLAR_T5_1000A:1165-01-01:0":{"b": ["Քըլըչ Արսլան II-ը վերցրեց Էլբիսթանը և Դարենդեն", "7c109007"], "d": ["Դանիշմենդյանների միջև վեճից օգտվելով՝ Քըլըչ Արսլան II-ը գրավեց Էլբիսթանը, Դարենդեն և Գեդյուքի շրջանը։", "d258bac6"]},
"OLAYLAR_T5_1000A:1172-01-01:0":{"b": ["Ռուբինյան Մլեհը Տարսոնը վերցրեց Բյուզանդիայից", "2f98fd11"], "d": ["Ռուբինյան Մլեհը Նուր ալ-Դին Զանգիի օգնությամբ Ադանան, Մամեստիան և Տարսոնը ետ վերցրեց բյուզանդացիներից։", "e1cfa006"]},
"OLAYLAR_T5_1000A:1174-01-01:0":{"b": ["Իլդեգիզյան Փեհլիվանը վերցրեց Թավրիզը", "f0831f17"], "d": ["Իլդեգիզյան Փեհլիվանը Թավրիզը խաղաղ ճանապարհով վերցրեց Ահմադիլյաններից և տվեց իր եղբայր Քըզըլ Արսլանին։", "81ee8ab8"]},
"OLAYLAR_T5_1000A:1175-01-01:0":{"b": ["Քըլըչ Արսլան II-ը Սեբաստիան և Նիքսարը վերցրեց Դանիշմենդյաններից", "584575bb"], "d": ["Նուր ալ-Դին Զանգիի մահից հետո Քըլըչ Արսլան II-ը 1175 թ. ամռանը գրավեց Սեբաստիան, Նիքսարը, Թոքաթը և Դանիշմենդյան մյուս հողերը. Սեբաստիայի ճյուղը վերացավ։", "c8092aea"]},
"OLAYLAR_T5_1000A:1178-10-25:0":{"b": ["Քըլըչ Արսլան II-ը վերցրեց Մալաթիան, Դանիշմենդյան ճյուղն ավարտվեց", "3bdbb060"], "d": ["Չորսամսյա պաշարումով Մալաթիան անցավ սելջուկներին, և Դանիշմենդյանների Մալաթիայի ճյուղը վերացավ։", "b92d6ebb"]},
"OLAYLAR_T5_1000A:1183-04-29:0":{"b": ["Սալահ ալ-Դինը վերցրեց Ամիդը և տվեց Արթուկյան Նուր ալ-Դին Մուհամմեդին", "8c3cc7bb"], "d": ["Սալահ ալ-Դին Այյուբին պաշարեց և վերցրեց Ամիդը, ապա տվեց Հիսն Քայֆայի Արթուկյան ամիրա Նուր ալ-Դին Մուհամմեդին. Ինալօղուլները վերացան։", "b16cdda4"]},
"OLAYLAR_T5_1000A:1184-01-01:0":{"b": ["Ռուբեն III-ը Ադանան ետ վերցրեց խաչակիրներից", "e9876f85"], "d": ["Մլեհից հետո որոշ ժամանակ խաչակիրներին անցած Մամեստիան, Ադանան և Թիլ Համդունը Ռուբինյան Ռուբեն III-ը ետ վերցրեց 1184 թ.։", "177b5432"]},
"OLAYLAR_T5_1000A:1190-01-01:0":{"b": ["Թիքրիթը անցավ Աբբասյաններին", "e8f5aeac"], "d": ["Բեգթեգինյան տիրապետությունից հետո քաղաքը անցավ Աբբասյան խալիֆայության վարչության տակ։", "f91cfb0d"]},
"OLAYLAR_T5_1000A:1194-01-01:0":{"b": ["Ռուքն ալ-Դին Սուլեյման շահ II-ը ետ վերցրեց Սամսունը", "0971ebcd"], "d": ["Եղբայրների կռիվների ընթացքում Կոմնենոսներին անցած Սամսունը և Արևելյան Սևծովյան հողերը ետ վերցրեց Սուլեյման շահը։", "940e4b5b"]},
"OLAYLAR_T5_1000A:1199-01-06:0":{"b": ["Ադանա և Տարսոն. Ռուբինյան իշխանությունը վերածվեց Կիլիկիայի հայկական թագավորության", "de3c4beb"], "d": ["Ադանան և Տարսոնը ձեռքին պահող Ռուբինյան հարստությունը ստացավ թագավորի տիտղոս. սա նույն հարստության տիտղոսի փոփոխությունն է, հողը ձեռքից ձեռք չանցավ։ Թագադրման օրը TDV-ում ՉԻ ԳՏՆՎԵԼ. թվականը ժառանգվել է Կիլիկիայի հայկական թագավորության քարտի սկզբից (քարտի օրը աղբյուր չէ)։", "be8faf2b"]},
"OLAYLAR_T5_1000A:1204-01-01:0":{"b": ["Հիմնվեց Տրապիզոնի կայսրությունը — Կիրասոնը և Սինոպը նույնպես նրա սահմաններում", "a99b6ba0"], "d": ["Լատինների կողմից Ստամբուլի գրավման պատճառով Տրապիզոն փախած Ալեքսիոս Կոմնենոսը իրեն հռչակեց կայսր. քաղաքը դարձավ նոր պետության կենտրոնը։ Կոմնենոսների թոռներ Ալեքսիոսի և Դավթի հիմնած պետությունը ձգվեց մինչև Սինոպ. Կիրասոնը նույնպես մնաց Տրապիզոնի կայսրության սահմաններում։", "dd95df25"]},
"OLAYLAR_T5_1000A:1204-04-13:0":{"b": ["Քյոթահիան Նիկիայի (Լասկարիսների) կայսրության տիրապետության ներքո — աղբյուրի թվագրված վկայությունը", "d91fa405"], "d": ["Աղբյուրը Քյոթահիա քաղաքը այս թվականին ցույց է տալիս Նիկիայի (Լասկարիսների) կայսրության վարչության ներքո. ավելի վաղ տիրապետությունը աղբյուրում թվագրված չէ (ատլասը այս թվականից առաջվա շրջանը թողնում է դատարկ)։", "50f100b1"]},
"OLAYLAR_T5_1000A:1205-01-01:0":{"b": ["Իլդեգիզյան Աբու Բաքրը վերցրեց Մարաղան", "03faed10"], "d": ["Ահմադիլյան Ալա ալ-Դին Քյորփեարսլանը ստիպված եղավ Մարաղայի ամրոցը թողնել Իլդեգիզյան աթաբեկ Աբու Բաքրին։", "742aae78"]},
"OLAYLAR_T5_1000A:1206-01-01:0":{"b": ["Սելջուկները գրավեցին Դենիզլին և Հոնազը", "1053ccc8"], "d": ["Ղիյաս ալ-Դին Քայխոսրով I-ի երկրորդ սուլթանության ժամանակ Դենիզլին և Հոնազը անցան սելջուկներին (բյուզանդական աղբյուրները նշում են 1196, «selcuklular» հոդվածը՝ 603/1207)։", "c102dae3"]},
"OLAYLAR_T5_1000A:1208-07-16:0":{"b": ["Ղիյաս ալ-Դին Քայխոսրով I-ը Մարաշը կրկին միացրեց սելջուկյան տերությանը", "91b1544e"], "d": ["Քայխոսրովը արշավանք կազմակերպեց հայերի դեմ և Մարաշը միացրեց սելջուկյան հողերին։", "5ffaa2f3"]},
"OLAYLAR_T5_1000A:1211-01-01:0":{"b": ["Կաստամոնուն Չոբանօղուլների տիրապետության ներքո — աղբյուրի թվագրված վկայությունը", "10b682ba"], "d": ["Աղբյուրը Կաստամոնու քաղաքը այս թվականին ցույց է տալիս Չոբանօղուլների վարչության ներքո. ավելի վաղ տիրապետությունը աղբյուրում թվագրված չէ (ատլասը այս թվականից առաջվա շրջանը թողնում է դատարկ)։", "1cdb9e90"]},
"OLAYLAR_T5_1000A:1214-11-02:0":{"b": ["Իզզ ալ-Դին Քայքավուս I-ը գրավեց Սինոպը", "463ea2b9"], "d": ["Սելջուկ սուլթան Իզզ ալ-Դին Քայքավուս I-ը Սինոպը վերցրեց Տրապիզոնի Կոմնենոսներից։", "0a71d5c6"]},
"OLAYLAR_T5_1000A:1222-01-01:0":{"b": ["Ալա ալ-Դին Քայկուբադ I-ը վերցրեց Կալոնորոսը (Ալաիե)", "5a4d6ac2"], "d": ["Անթալիայից արևելք գտնվող Կալոնորոս ամրոցը սելջուկները վերցրին, վերակառուցեցին, և այն ստացավ Ալաիե անունը («alanya» հոդվածը նշում է 1221)։", "a00756da"]},
"OLAYLAR_T5_1000A:1225-01-01:0":{"b": ["Ջալալ ալ-Դին Խորեզմշահը բռնակցեց Ատրպատականը", "5b812b99"], "d": ["Ջալալ ալ-Դին Խորեզմշահը Ատրպատականը և Առանը միացրեց իր հողերին (տարածաշրջանի մասին նախադասություն)։", "5bba4780"]},
"OLAYLAR_T5_1000A:1225-07-01:0":{"b": ["Ջալալ ալ-Դին Խորեզմշահը վերցրեց Մարաղան", "a55ec004"], "d": ["Ջալալ ալ-Դին Խորեզմշահը գրավեց Մարաղան և այն դարձրեց Ատրպատականի ռազմական և վարչական կենտրոնը։", "2aa8a852"]},
"OLAYLAR_T5_1000A:1225-07-25:0":{"b": ["Ջալալ ալ-Դին Խորեզմշահը մտավ Թավրիզ", "72904097"], "d": ["Երբ աթաբեկ Օզբեկը նահանջեց Գանձակ, Ջալալ ալ-Դին Խորեզմշահը մտավ Թավրիզ, տիրեց քաղաքին և այն դարձրեց իր կենտրոնը։", "43ee9867"]},
"OLAYLAR_T5_1000A:1228-01-01:0":{"b": ["Ալա ալ-Դին Քայկուբադը վերցրեց Կամախը", "8c5aa655"], "d": ["Մենգուջեքյանների Կամախ-Երզնկայի ճյուղը Կամախը պաշարած և վերցրած Ալա ալ-Դին Քայկուբադ I-ի կողմից միացվեց սելջուկյան հողերին։", "7edb7223"]},
"OLAYLAR_T5_1000A:1231-01-01:0":{"b": ["Մարաղան մոնղոլների կողմից գրավվեց երկրորդ անգամ", "f1320e5d"], "d": ["Խորեզմշահի տիրապետության վերջում Մարաղան անցավ մոնղոլների ձեռքը։", "9cee2a89"]},
"OLAYLAR_T5_1000A:1231-01-01:1":{"b": ["Ատրպատականն անցավ մոնղոլական տիրապետության տակ — Թավրիզը ենթարկվեց մոնղոլական գրավման", "3f38ef66"], "d": ["Ջալալ ալ-Դին Խորեզմշահի անկմամբ Թավրիզը 1231 թ. ենթարկվեց մոնղոլական գրավման. մոնղոլական տիրապետությունը նույն տարում ընդգրկեց Հյուսիսային և Հարավային Ատրպատականը (տարածաշրջանի մասին նախադասություն, քաղաքին հատուկ չէ)։ Շիրվանում (Բաքու, Շամախի) Շիրվանշահերը մոնղոլական իշխանության ներքո շարունակեցին գոյատևել որպես տեղական հարստություն. ատլասը այս երկու կետը Էմրեի որոշմամբ պահում է Շիրվանշահերի գույնով (մոնղոլական/իլխանական վասալությունը նշված է ծանոթագրությունում)։", "46225c2e"]},
"OLAYLAR_T5_1000A:1232-10-01:0":{"b": ["Այյուբյան ալ-Մալիք ալ-Քամիլը վերցրեց Ամիդը", "9cebe681"], "d": ["Ալ-Մալիք ալ-Քամիլը պաշարելով Ամիդը վերցրեց Արթուկյաններից։", "02085ee1"]},
"OLAYLAR_T5_1000A:1233-01-01:0":{"b": ["Ալա ալ-Դին Քայկուբադ I-ը Քյոթահիան վերցրեց Նիկիայի կայսրությունից", "e0b9a7f7"], "d": ["1182 թվականից հետո խառնաշփոթների ժամանակ կրկին Բյուզանդիային անցած Քյոթահիան Ալա ալ-Դին Քայկուբադ I-ի օրոք ետ վերցվեց Նիկիայի կայսրությունից։", "90db8b27"]},
"OLAYLAR_T5_1000A:1233-01-01:1":{"b": ["Բադր ալ-Դին Լուլուն՝ Մոսուլի սուլթան", "73268628"], "d": ["Վերջին Զանգյան աթաբեկի մահով Բադր ալ-Դին Լուլուն խալիֆայի կողմից հռչակվեց սուլթան։ (Ռաբի ալ-ավվալ 631 / 1233 թ. դեկտեմբեր. ատլասը, հետևելով քարտին, գրում է տարվա ճշգրտությամբ։)", "076b23b0"]},
"OLAYLAR_T5_1000A:1234-08-01:0":{"b": ["Սելջուկները վերցրին Խարբերդը", "3b9391eb"], "d": ["Ալա ալ-Դին Քայկուբադի բանակը քսանչորսօրյա պաշարումով ընդունեց Խարբերդի ամրոցի հանձնումը. Խարբերդի Արթուկյանները վերացան։", "1ae6c0d9"]},
"OLAYLAR_T5_1000A:1240-07-23:0":{"b": ["Ղիյաս ալ-Դին Քայխոսրով II-ը գրավեց Ամիդը", "c37c3b04"], "d": ["Անատոլիայի սելջուկ սուլթան Ղիյաս ալ-Դին Քայխոսրով II-ը Ամիդը վերցրեց Այյուբյաններից։", "f8a0cc8c"]},
"OLAYLAR_T5_1000A:1253-01-01:0":{"b": ["Մունգկե խագանը Իֆթիհար ալ-Դինին նշանակեց Ղազվինի կուսակալ", "fc650d13"], "d": ["Մոնղոլների մեծ խան Մունգկեն նրան նշանակեց Ղազվինի կուսակալ. սկսվեց Իֆթիհարյանների շրջանը։", "c042dadd"]},
"OLAYLAR_T5_1000A:1256-01-01:0":{"b": ["Հուլագուի ժամանումը. Ղազվինը և Նախիջևանը անցան իլխանական կառավարման տակ", "24673608"], "d": ["Հուլագուի Իրան ժամանելով մոնղոլական կառավարումը փոխանցվեց Իլխանական պետությանը. Ղազվինը և Նախիջևանը անցան իլխանական կառավարման տակ (կանոն 5-ի սահման, ոչ թե աղբյուրի օրը)։ Շիրվանում (Բաքու, Շամախի) մոնղոլական օկուպացիան ծանր ավերածություն բերեց, սակայն Շիրվանշահերը գոյատևեցին որպես տեղական հարստություն. ատլասը այս երկու կետը պահում է Շիրվանշահերի գույնով (Էմրեի որոշում)։", "14d75e4f"]},
"OLAYLAR_T5_1000A:1257-01-01:0":{"b": ["Մոնղոլները գրավեցին Թիքրիթը", "60af2df0"], "d": ["Մոնղոլական ներխուժման ժամանակ Թիքրիթը գրավվեց և կողոպտվեց. քաղաքը դուրս եկավ Աբբասյան վարչությունից։", "1a51fdd7"]},
"OLAYLAR_T5_1000A:1257-03-27:0":{"b": ["Հուլագուն Համադանից շարժվեց դեպի Բաղդադ", "5f0c77b5"], "d": ["Հուլագուն Բաղդադի արշավանքի դուրս եկավ Համադանից, ուր գտնվում էին նրա բեռները (իլխանական տիրապետության վկայություն)։", "303cbae8"]},
"OLAYLAR_T5_1000A:1258-01-01:0":{"b": ["Բողաթիմուրը վերցրեց Կուֆան և Բասրան", "dec82b4e"], "d": ["Բողաթիմուրի ղեկավարած մոնղոլական ուժերը գրավեցին Կուֆան, Վասիտը և Բասրան։", "10fd1496"]},
"OLAYLAR_T5_1000A:1258-01-01:1":{"b": ["Իրաքն անցավ մոնղոլների ձեռքը (տարածաշրջանային)", "7b990281"], "d": ["1258 թ. Հուլագուի կողմից Բաղդադի գրավմամբ Աբբասյան պետությունը կործանվեց, և Իրաքն անցավ մոնղոլների ձեռքը։", "6f12d882"]},
"OLAYLAR_T5_1000A:1258-01-01:2":{"b": ["Մարաշը թողնվեց հայերին", "6161f1a5"], "d": ["Հուսամ ալ-Դինի ընտանիքից Իմադ ալ-Դինը, աջակցություն չգտնելով, Մարաշը թողեց Կիլիկիայի հայերին։", "9ea1e7ff"]},
"OLAYLAR_T5_1000A:1258-01-01:3":{"b": ["Վասիտն անցավ իլխանական տիրապետության տակ", "fbdf83fc"], "d": ["Իլխանների կողմից Իրաքի գրավմամբ Վասիտը անցավ նրանց վարչության տակ։", "5f4aee6b"]},
"OLAYLAR_T5_1000A:1258-02-10:0":{"b": ["Մոնղոլները վերցրին Բաղդադը. Աբբասյան խալիֆայության վախճանը", "41c34bd4"], "d": ["Հուլագուի հրամանատարությամբ մոնղոլները հարձակվեցին Բաղդադի վրա, խալիֆա Մուստասիմը հանձնվեց. քաղաքն անցավ իլխանական տիրապետության տակ։", "1c979d91"]},
"OLAYLAR_T5_1000A:1262-01-01:0":{"b": ["Մոնղոլները վերցրին Մոսուլը, Լուլուի հարստությունը վերացավ", "035d0121"], "d": ["Բայբարսի կողքին կանգնած ալ-Մալիք ալ-Սալիհ Իսմայիլի Մոսուլը ենթարկվեց մոնղոլական ավերածության, իսկ նա ինքը սպանվեց Հուլագուի ներկայությամբ։", "69cc41a9"]},
"OLAYLAR_T5_1000B:1069-10-20:0":{"b": ["Մեքքայի խուտբան Ֆաթիմյաններից շրջվեց Աբբասյան խալիֆայի և սուլթան Ալփ Արսլանի անունով", "df951887"], "d": ["Եգիպտոսի սովի պատճառով պարեն չգալիս Մեքքայի էմիր Աբու Հաշիմ Մուհամմեդ բ. Ջաֆարը խուտբան կարդացնել տվեց Աբբասյան խալիֆա ալ-Կաիմ Բի-ամր Ալլահի և սելջուկ սուլթան Ալփ Արսլանի անունով. Մեքքան անցավ Մեծ Սելջուկների գերիշխանության տակ։", "c8a5b1f7"]},
"OLAYLAR_T5_1000B:1075-01-01:0":{"b": ["Աթսիզ բ. Ուվաքը վերցրեց Դամասկոսը", "8eea047f"], "d": ["Աթսիզը գրավեց Սիրիան և խուտբան կարդացնել տվեց Աբբասյան խալիֆայի և Մելիքշահի անունով։", "1de51f0c"]},
"OLAYLAR_T5_1000B:1076-01-01:0":{"b": ["Մեքքայի էմիր Աբու Հաշիմը խուտբան կրկին կարդացնել տվեց Ֆաթիմյան խալիֆայի անունով", "85b6c0c0"], "d": ["Չնայած Մելիքշահի՝ սուննի ազդեցությունն ամրապնդելու ջանքերին՝ Մեքքայի էմիրը խուտբան կրկին սկսեց կարդացնել Ֆաթիմյանների անունով. Մեքքան վերադարձավ Ֆաթիմյան գերիշխանության տակ։", "a7ec64c5"]},
"OLAYLAR_T5_1000B:1079-01-01:0":{"b": ["Թութուշը մտավ Դամասկոս, հիմնվեցին Սիրիայի սելջուկները", "b48b38be"], "d": ["Թութուշը մտավ քաղաք և հիմնեց Սիրիայի Սելջուկյան պետությունը։", "6404e098"]},
"OLAYLAR_T5_1000B:1080-01-01:0":{"b": ["Մեքքայի էմիրը հայտնեց իր հավատարմությունը Աբբասյան խալիֆա Մուկթադիին և սուլթան Մելիքշահին", "38a430a5"], "d": ["Մեքքայի էմիրը կրկին ենթարկվեց Աբբասյան խալիֆային և սելջուկ սուլթանին. այս հավատարմությունը տևեց մինչև Մելիքշահի մահը (1092)։", "41ad14e9"]},
"OLAYLAR_T5_1000B:1092-01-01:0":{"b": ["Սուլթան Մելիքշահի մահից հետո Մեքքայում խուտբան կրկին վերադարձավ Ֆաթիմյաններին", "195a27cd"], "d": ["Սելջուկ սուլթան Մելիքշահի մահից հետո Մեքքայի էմիրը խուտբաները կրկին սկսեց կարդացնել Ֆաթիմյան խալիֆայի անունով. Մեքքան անցավ Ֆաթիմյան գերիշխանության տակ։", "00e9a74b"]},
"OLAYLAR_T5_1000B:1097-07-01:0":{"b": ["Դորիլեոնի պարտությունից հետո Էսքիշեհիրը վերադարձավ Բյուզանդիային", "3f381ee4"], "d": ["Խաչակիրների առջև Քըլըչ Արսլան I-ի նահանջից հետո քաղաքը կրկին անցավ բյուզանդական վարչության տակ։", "f3155b07"]},
"OLAYLAR_T5_1000B:1104-06-06:0":{"b": ["Թուղթեգինը հիմնեց Դամասկոսի աթաբեկությունը", "f26729c0"], "d": ["Դուքաքի մահից հետո աթաբեկ Թուղթեգինը հիմնեց Բուրիների հարստությունը։", "ac9e7419"]},
"OLAYLAR_T5_1000B:1150-01-01:0":{"b": ["Ալմոհադները վերցրին Մեքնեսը", "ee976b41"], "d": ["Երկար դիմադրությունից հետո քաղաքը անցավ Ալմոհադների տիրապետության տակ և կողոպտվեց։", "4924b727"]},
"OLAYLAR_T5_1000B:1154-04-25:0":{"b": ["Նուր ալ-Դին Զանգին վերցրեց Դամասկոսը", "a4fd8b58"], "d": ["Նուր ալ-Դին Մահմուդը Դամասկոսը դրեց իր տիրապետության տակ։", "f87fe7de"]},
"OLAYLAR_T5_1000B:1171-09-13:0":{"b": ["Եգիպտոսում ավարտվեց Ֆաթիմյան իշխանությունը, իշխանության եկան Այյուբյանները — Ալեքսանդրիա, Ֆայում և Մեքքա (Հիջազ)", "1c565534"], "d": ["Սալահ ալ-Դինի վեզիրությամբ և Ֆաթիմյան խալիֆա ալ-Ադիդի մահով (567/1171) Եգիպտոսն անցավ Այյուբյաններին. Ալեքսանդրիան և Ֆայումը անցան Այյուբյան վարչության տակ։ Օրը աղբյուրում նշված չէ. ժառանգվել է Ֆաթիմյան քարտի ավարտից (քարտի օրը աղբյուր չէ)։ Հիջազը նույնպես անցավ Այյուբյան վարչության տակ. Մեքքայի գերիշխանությունը Ֆաթիմյաններից անցավ Այյուբյաններին (Էմրե #23 գերիշխանության մոդել)։", "191ac5be"]},
"OLAYLAR_T5_1000B:1174-01-01:0":{"b": ["Սալահ ալ-Դինը վերցրեց Դամասկոսը", "dfdb11ce"], "d": ["Նուր ալ-Դինի մահից հետո քաղաքը անցավ Սալահ ալ-Դին Այյուբիին։", "a20855b8"]},
"OLAYLAR_T5_1000B:1176-09-17:0":{"b": ["Միրիոկեֆալոնից հետո Բյուզանդիան ազատեց Դորիլեոնը", "24aef255"], "d": ["Միրիոկեֆալոնի պարտությունից հետո Մանուելը պայմանագրի համաձայն քանդեց Դորիլեոնի ամրությունները և ազատեց քաղաքը. թուրքերը այստեղ սկսեցին կոչել Էսքիշեհիր։", "d56a7724"]},
"OLAYLAR_T5_1000B:1178-01-01:0":{"b": ["Ամասիան միացվեց սելջուկյան հողերին", "cf56b964"], "d": ["Քըլըչ Արսլան II-ը Դանիշմենդյան հողերը (ներառյալ Ամասիան) միացրեց սելջուկյան երկրին։", "ddbb98aa"]},
"OLAYLAR_T5_1000B:1187-01-01:0":{"b": ["Ասեն եղբայրները վերցրին Հյուսիսային Բուլղարիան. Բյուզանդիան ճանաչեց Բուլղարական II պետությունը", "ff0554e9"], "d": ["Պետր և Ասեն եղբայրները կումանների աջակցությամբ կրկին վերցրին Հյուսիսային Բուլղարիան. 1187 թ. հաշտությամբ Բյուզանդիան ճանաչեց Բուլղարական II պետությունը։", "fc165cbf"]},
"OLAYLAR_T5_1000B:1189-01-01:0":{"b": ["Սերբիան ամրապնդեց իր տիրապետությունը Զետայում", "794c821d"], "d": ["1189 թ. Սերբիան ամրապնդեց իր տիրապետությունը Զետայի (ներառյալ Կոտորի ափը) վրա. Զետային ճանաչվեց հատուկ կարգավիճակ։", "5f16f312"]},
"OLAYLAR_T5_1000B:1192-01-01:0":{"b": ["Գի դը Լուզինյանը գնեց Կիպրոսը, Նիկոսիան դարձավ մայրաքաղաք", "11017aea"], "d": ["Գի դը Լուզինյանը կղզին գնեց տամպլիերներից և Նիկոսիան դարձրեց մայրաքաղաք։", "b6494b99"]},
"OLAYLAR_T5_1000B:1201-03-01:0":{"b": ["Կալոյանը գրավեց Վառնան", "1237fe7f"], "d": ["Ցար Կալոյանի հրամանատարությամբ բուլղարները 1201 թ. մարտին Վառնան վերցրին Բյուզանդիայից. քաղաքը XIII-XIV դարերում մնաց Բուլղարական պետության սահմաններում։", "b60444f8"]},
"OLAYLAR_T5_1000B:1202-01-01:0":{"b": ["Նիշապուրը վերջնականապես միացավ Խորեզմշահերին", "fa4a6cd2"], "d": ["Ալա ալ-Դին Մուհամմեդ բ. Թեքիշը քաղաքը վերջնականապես միացրեց Խորեզմշահերի հողերին։", "58cb9059"]},
"OLAYLAR_T5_1000B:1204-04-13:0":{"b": ["Գալիպոլիի թերակղզին անցավ լատինական վարչության տակ", "27308f59"], "d": ["IV խաչակրաց արշավանքից հետո Գալիպոլին և նրա շրջանը 1204 թ. անցան լատինների վարչության տակ։", "48b977ad"]},
"OLAYLAR_T5_1000B:1204-04-13:1":{"b": ["Հիմնվեց Էպիրոսի դեսպոտությունը — Յանինան դարձավ կենտրոն, Լեպանտոն անցավ դեսպոտությանը", "d7966877"], "d": ["IV խաչակրաց արշավանքից հետո Միքայել Անգելոսը հիմնեց Էպիրոսի դեսպոտությունը. Յանինան դարձվեց դեսպոտության կենտրոն, Լեպանտոն նույնպես մնաց դեսպոտության հողերում։", "632eac4c"]},
"OLAYLAR_T5_1000B:1204-08-12:0":{"b": ["Կրետեն վաճառվեց Վենետիկին", "f1760e84"], "d": ["Մոնֆերատի մարկիզ Բոնիֆացիոսը 1204 թ. օգոստոսի 12-ի համաձայնագրով Կրետեն 100.000 արծաթով զիջեց Վենետիկին։", "cdb2570d"]},
"OLAYLAR_T5_1000B:1219-01-01:0":{"b": ["Հիմնվեց Մանսուրան", "342a6f47"], "d": ["Ալ-Մալիք ալ-Քամիլը Դամիետան գրաված խաչակիրների դեմ հիմնեց Մանսուրան որպես ռազմակայան։", "35189819"]},
"OLAYLAR_T5_1000B:1221-04-10:0":{"b": ["Մոնղոլները վերցրին Նիշապուրը", "0e73f075"], "d": ["Մոնղոլական ներխուժմամբ քաղաքը ավերվեց։", "be55c768"]},
"OLAYLAR_T5_1000B:1229-01-01:0":{"b": ["Ռասուլյան Նուր ալ-Դին Օմարը Եմենը դրեց իր վարչության տակ", "ee1ec7ab"], "d": ["Եմենի վերջին Այյուբյան ալ-Մասուդի մահից հետո Նուր ալ-Դին Օմարը տիրեց Եմենին։", "02cf9719"]},
"OLAYLAR_T5_1000B:1235-01-01:0":{"b": ["Նիկիայի կայսր Վատացեսը ետ վերցրեց Գալիպոլին", "a6936e33"], "d": ["Նիկիայի կայսր Հովհաննես III Վատացեսը Գալիպոլին ետ վերցրեց լատիններից (1235)։", "184a089e"]},
"OLAYLAR_T5_1000B:1243-07-01:0":{"b": ["Մոնղոլները գրավեցին Ամասիան", "783bcd0c"], "d": ["Քյոսեդաղից հետո մոնղոլները վերցրին քաղաքը. այն կառավարեցին մոնղոլ կուսակալները։", "4e46e2df"]},
"OLAYLAR_T5_1000B:1246-01-01:0":{"b": ["Վատացեսն անցավ Թրակիա. Էդիրնեն և Սալոնիկը միացան Նիկիայի կայսրությանը", "0bf61ca5"], "d": ["Նիկիայի տիրակալ Հովհաննես III Վատացեսը 1246 թ. անցնելով Թրակիա՝ գրավեց բուլղարների զբաղեցրած հողերը և Սալոնիկը։", "73992921"]},
"OLAYLAR_T5_1000B:1250-01-01:0":{"b": ["Ռասուլյան տիրապետությունը ճանաչվում էր Մեքքայում — Նուր ալ-Դին Օմարը զոհ դարձավ մահափորձի", "d7e03c21"], "d": ["Երբ Եմենի Ռասուլյան սուլթան Նուր ալ-Դին Օմարը սպանվեց Ջանադում (1250 թ. փետրվար), նրա պետության տիրապետությունը ճանաչվում էր Մեքքայի և Հադրամաուտի միջև. Այյուբյան սուլթանության վերացման տարում Մեքքան երևում է Ռասուլյան գերիշխանության տակ։", "ba654624"]},
"OLAYLAR_T5_1000B:1250-04-30:0":{"b": ["Եգիպտոսում հիմնվեց Մամլուքների պետությունը — Ալեքսանդրիան, Մանսուրան և Ֆայումը անցան մամլուքներին", "230c1a11"], "d": ["Թուրան շահից հետո Շաջարաթ ալ-Դուրի և Իզզ ալ-Դին Այբաքի հետ հաստատվեց մամլուքական իշխանությունը. Եգիպտոսի քաղաքները (Ալեքսանդրիա, Մանսուրա, Ֆայում) անցան մամլուքական վարչության տակ։ Աղբյուրը Այբաքի գահակալումը նշում է 1250 թ. հուլիսի 3. ատլասը օրը ժառանգել է Այյուբյան քարտի ավարտից (1250 թ. ապրիլի 30). քարտի օրը աղբյուր չէ, տարբերությունը հայտնված է։", "f9743bcd"]},
"OLAYLAR_T5_1000B:1250-04-30:1":{"b": ["Հալեպի Այյուբյան ան-Նասիր Յուսուֆը տիրեց Դամասկոսին", "d585985d"], "d": ["Մինչ Եգիպտոսում հաստատվում էր մամլուքական իշխանությունը, Հալեպի տիրակալ ան-Նասիր Յուսուֆը վերցրեց Դամասկոսը (648/1250)։", "c05ddddc"]},
"OLAYLAR_T5_1000B:1253-04-01:0":{"b": ["Երուսաղեմը հաշտությամբ զիջվեց մամլուքներին", "50d53fac"], "d": ["Խալիֆայի միջնորդությամբ կնքված հաշտությամբ Երուսաղեմը զիջվեց մամլուքներին։", "82982e3a"]},
"OLAYLAR_T5_1000B:1256-01-01:0":{"b": ["Երուսաղեմը կրկին անցավ Այյուբյաններին", "fdeedd4a"], "d": ["Պաղեստինը և Երուսաղեմը կրկին անցան Սիրիայի Այյուբյանների ձեռքը։", "46a6e2a9"]},
"OLAYLAR_T5_1000B:1260-03-01:0":{"b": ["Մոնղոլները վերցրին Դամասկոսը", "430bdfea"], "d": ["Հուլագուի Սիրիայի արշավանքի ժամանակ Դամասկոսն անցավ մոնղոլներին։", "407e5d3f"]},
"OLAYLAR_T5_1000B:1260-09-03:0":{"b": ["Այն Ջալութի ճակատամարտը. Դամասկոսը և Երուսաղեմը անցան մամլուքներին", "40ebd7b7"], "d": ["Քութուզը Այն Ջալութում հաղթեց մոնղոլներին (25 Ռամադան 658 / 1260 թ. սեպտեմբերի 3). Սիրիայի մեծ մասը, Դամասկոսը և Երուսաղեմը անցան մամլուքների ձեռքը, Այյուբյան հարստությունը վերացավ։", "619c8015"]},
"OLAYLAR_T5_1000B:1261-06-09:0":{"b": ["Բայբարսը Կահիրեում վերականգնեց Աբբասյան խալիֆայությունը — Մեքքան և Մեդինան կապվեցին մամլուքների հետ", "a5128a1e"], "d": ["Բայբարսը Բաղդադի կործանումից փրկված Աբբասյան Ահմեդին Կահիրեում հռչակեց խալիֆա և հավատարմության երդում տվեց. խալիֆայության պաշտպանի հանգամանքով նա երկու Սուրբ վայրերը (Հարամայն) նույնպես կապեց մամլուքական գերիշխանությանը։ Օրը խալիֆայության վերականգնմանն է. Մեքքայի և Մեդինայի կապվելու օրը աղբյուրում նշված չէ (ստորին սահման)։", "638d550a"]},
"OLAYLAR_T5_1000B:1261-07-25:0":{"b": ["Նիկիայի զորամասերը մտան Ստամբուլ — Բյուզանդական կայսրությունը վերականգնվեց", "81741490"], "d": ["Նիկիայի զորամասերը 1261 թ. հուլիսի 25-ին մտան Ստամբուլ և վերջ դրեցին լատինական տիրապետությանը. Լասկարիսների (Նիկիայի) պետության հողերը՝ Բուրսան, Իզմիրը, Չիմպեն, Էդիրնեն, Սալոնիկը, կրկին դարձան Բյուզանդական կայսրություն։ Ատլասը այս կետերում 1261-ից առաջ Նիկիայի կայսրության շրջանը ցույց է տալիս միայն աղբյուրում անունով հիշատակվողների դեպքում։", "b389b508"]},
"OLAYLAR_T5_1000B:1271-01-01:0":{"b": ["Շառլ Անժուացին վերցրեց Դուրեսը և Կրույան", "082a86b8"], "d": ["Անժու հարստությունից Շառլը 1271-1272 թվականներին վերցրեց Դուրեսը և Կրույան և վերակառուցել տվեց հին ամրոցը։", "e9f84d14"]},
"OLAYLAR_T5_1000B:1284-01-01:0":{"b": ["Սիցիլիացիները գրավեցին Ջերբա կղզին", "daab5ad2"], "d": ["Ջերբա կղզին 683 (1284-85) թվականին գրավվեց սիցիլիացիների կողմից. նախ դարձավ պապականության կալվածք, ապա ենթարկվեց Սիցիլիայի թագավորությանը։", "691035b3"]},
"OLAYLAR_T5_1000B:1318-01-01:0":{"b": ["Յանինան կրկին միացավ Բյուզանդական կայսրությանը", "60016303"], "d": ["XIII դարի երկրորդ կեսին բազմիցս ձեռքից ձեռք անցած Յանինան 1318 թ. կրկին միացավ Բյուզանդիային, սակայն որոշ չափով պահպանեց ինքնավարությունը. Էպիրոսի դեսպոտության կենտրոնը տեղափոխվեց Արտա։", "14c24d12"]},
"OLAYLAR_T5_1000B:1334-01-01:0":{"b": ["Ջերբայի ժողովուրդը կղզուց վտարեց սիցիլիացիներին", "ff71985e"], "d": ["Սիցիլիայի կուսակալների վատ կառավարման դեմ ապստամբած կղզու ժողովուրդը 1334 թ. վտարեց սիցիլիացիներին. Ջերբան կրկին անցավ Հաֆսյան վարչության տակ։", "1ddb9780"]},
"OLAYLAR_T5_1000B:1363-01-01:0":{"b": ["Շառլ Թոպիան տիրեց Կրույային", "4e40583d"], "d": ["Ցար Դուշանի մահից (1355) հետո ալբանացի Շառլ Թոպիան տիրեց Կրույային։", "7af64cd2"]},
"OLAYLAR_UMIT19_ASIRET_1119:1722-04-05:0":{"b": ["Ռոգեվենը տեսավ Զատկի կղզին և անվանեց Paasch Eyland. կղզում մարդկանց ապրելը պարզ դարձավ հաջորդ օրը՝ ծխերից", "c6940261"], "d": ["Յակոբ Ռոգեվենի արշավախումբը, ըստ պաշտոնական նավամատյանի, 1722 թ. ապրիլի 5-ին տեսավ ցածր և հարթ կղզի և, քանի որ Զատկի օրն էր, անվանեց Paasch Eyland։ Ապրիլի 6-ին տարբեր վայրերից բարձրացող ծխեր երևացին, և եզրակացվեց, որ կղզում մարդիկ են ապրում. Բերենսի պատումը հայտնագործությունը դնում է ապրիլի 6-ին։", "32641f88"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-08-13:0":{"b": ["Սալիվանի արշավանքի առաջապահ զորամասերը այրեցին Չեմունգ (Chemong) գյուղը", "2656fcd6"], "d": ["Սալիվանի բանակը 1779 թ. օգոստոսի 12-ի երեկոյան Թիոգայից գիշերային երթի ելավ և հաջորդ առավոտ լուսաբացին հասավ Չեմունգ գյուղ. գյուղացիները նախապես փախել էին։ Զորամասերը այրեցին գյուղի մոտ քսան շինությունները և ավերեցին շրջակա եգիպտացորենի դաշտերը։", "07caaa80"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-08-29:0":{"b": ["Նյութաունի ճակատամարտ. Սալիվանի արշավանքը ցրեց Կայուգա և Սենեկա ցեղերը ներառող իրոկեզ ռազմիկների՝ Չեմունգի մոտ գտնվող ամրությունը", "2383ea65"], "d": ["Գեներալ-մայոր Սալիվանի բանակը 1779 թ. օգոստոսի 29-ին Չեմունգի մոտ բախվեց ամրության, որը պատրաստել էին, ըստ Սալիվանի նամակի, «յոթ ազգերի» հնդկացի ռազմիկները (Բաթլերների, Բրանտի և Մակդոնալդի առանձին հրամանատարությամբ ուժերի հետ միասին). հրետանային կրակի և գեներալ Պուրի կողային ճնշման տակ ամրությունը լքվեց։", "3adfc9de"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-02:0":{"b": ["Սալիվանի բանակը ոչնչացրեց Catharine's Town գյուղը և նրա եգիպտացորենը", "62b91293"], "d": ["Սալիվանի արշավանքի բանակը 1779 թ. սեպտեմբերի 1-ի գիշերը հասավ Սենեկա լճի մոտ գտնվող Catharine's Town. սեպտեմբերի 2-ին ոչնչացրեց գյուղը և ցանած եգիպտացորենը։ Գյուղը երեսուն տնով, այգիներով և առատ եգիպտացորենով բնակավայր էր։", "d56e8155"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-05:0":{"b": ["Սալիվանի բանակը մտավ Կենդայա գյուղ. մոտ քսան տուն մոխրի վերածվեց, ցանքերն ու պտղատու ծառերը ավերվեցին", "68c01d89"], "d": ["Սալիվանի բանակը 1779 թ. սեպտեմբերի 5-ին հասավ Կենդայա գյուղ. ըստ Սալիվանի զեկույցի՝ գյուղը լքված էր։ Ռոջերսի օրագիրը գրում է, որ գյուղը ոչնչացվեց, Սալիվանի պաշտոնական զեկույցը՝ որ մոտ քսան տուն մոխրի վերածվեց, և բանակը մոտ մեկ օր ավերեց ցանքերն ու պտղատու ծառերը։", "f29f4983"]},
"OLAYLAR_UMIT19_ASIRET_1119:1779-09-15:0":{"b": ["Սալիվանի բանակը ոչնչացրեց Genesee (Chenesee) Town-ը և եգիպտացորենի ու լոբու ցանքերը", "c5e8f3be"], "d": ["Սալիվանի բանակը 1779 թ. սեպտեմբերի 14-ին մտավ մոտ յոթանասուն տուն ունեցող Genesee (Chenesee) Town. սեպտեմբերի 15-ին ամբողջ բանակը դուրս եկավ դաշտ ցանքերը ոչնչացնելու, եգիպտացորենն ու լոբին այրվեցին, և վերադարձի երթը սկսելիս գյուղերը թողնվեցին բոցերի մեջ։", "3a04a429"]},
"OLAYLAR_UMIT19_ASIRET_1119:1830-10-07:0":{"b": ["Վան Դիմենի երկրում սկսվեց Սև գծի (Black Line) գործողությունը. գաղութաբնակները զորահավաքվեցին Թասմանիայի բնիկներին բռնելու համար", "d2ffdfcb"], "d": ["Կուսակալ Արթուրի՝ Գաղութային քարտուղարության 1830 թ. սեպտեմբերի 25-ի հայտարարությունը հայտնեց, որ ժողովուրդը 1830 թ. հոկտեմբերի 7-ին միահամուռ գործողության է անցնելու, իսկ մայոր Դուգլասը նույն օրը գծի երկայնքով զբաղեցնելու է դիտակետերը։ Նպատակը բնիկ ցեղերին բռնելն ու Թասմանի թերակղզու կողմ քշելն էր։", "a7114cb5"]},
"OLAYLAR_UMIT19_ASIRET_1119:1830-11-26:0":{"b": ["Սև գծի գործողության առաջին շարքը պաշտոնապես ավարտվեց. Կառավարական հրաման № 13", "861ffa50"], "d": ["1830 թ. նոյեմբերի 26-ի Կառավարական հրաման № 13-ը հայտնեց, որ տեղական ցեղերին բռնելուն ուղղված գործողությունների առաջին շարքը փակվեց զինվորական և քաղաքացիական զորամասերի՝ East Bay Neck հասնելով։", "a4f38ca9"]},
"OLAYLAR_UMIT19_ASIRET_1119:1850-07-18:0":{"b": ["Ռիչարդսոն–Բարտ–Օվերվեգ արշավախումբը Սահարայի ճանապարհին Մուրզուկից հետո հասավ երկրորդ մեծ կայան՝ Գաթ (Ghat)", "f52b2fa6"], "d": ["Հայնրիխ Բարտի՝ Ռիչարդսոնի գլխավորած բրիտանական կառավարական արշավախմբով Սահարան անցնելիս 1850 թ. հուլիսի 18-ի օրագրային գրառման մեջ պատմվում է արշավախմբի երկրորդ մեծ կայանը համարվող Գաթին (Ghat) մոտենալն ու հասնելը. բնակիչներից ոմանք ճանաչեցին և դիմավորեցին Ռիչարդսոնին, որը նախկինում էլ այցելել էր այս վայրը։ Սա շրջանի առաջին եվրոպական այցը չէ։", "2e9bb2a4"]},
"OLAYLAR_UMIT19_ASIRET_1119:1869-07-13:0":{"b": ["Գուստավ Նախտիգալը հասավ Տիբեստիի գլխավոր հովիտներից Տաո (Täo)", "bc67c7f0"], "d": ["Գուստավ Նախտիգալը Մուրզուկից եկող իր քարավանով առաջացավ Տիբեստիի լեռնազանգվածի հարավարևմտյան ստորոտով. «Sahara և Sudan» գրքում հուլիսի 13-ին պատմում է Տիբեստիի գլխավոր հովիտներից և ազնվական ընտանիքների բուն հայրենիք նկարագրվող Տաո հովիտ հասնելը (գրքի «Ankunft in Täo» գլուխը)։ Գրում է, որ նույն օրվա առավոտյան մտան Տաոյի գետահուների հարթավայր, ապա հանդիպեցին Բյու Զեիդի ազգական Գալմային։", "f8941a27"]},
"OLAYLAR_UMIT19_ASIRET_1119:1874-05-06:0":{"b": ["Էռնեստ Ջայլսը, ի հիշատակ կորած ընկերոջ՝ Ալֆրեդ Գիբսոնի, Ռաուլինսոնի լեռնաշղթայից արևմուտք ընկած անապատը անվանեց «Gibson's Desert»", "7ad5e61f"], "d": ["Էռնեստ Ջայլսի Արևմտյան Ավստրալիայի արշավախումբը (սկսվել էր 1873 թ. օգոստոսին) Ռաուլինսոնի լեռնաշղթայից արևմուտք մտավ անապատ. նրա ընկեր Ալֆրեդ Գիբսոնը այս անապատում կորավ Ջայլսի ձիով։ Ջայլսը 1874 թ. մայիսի 6-ի օրագրում գրում է, որ Ռաուլինսոնի լեռնաշղթայի և հաջորդ մշտական ջրի միջև ընկած այս շրջանը անվանեց «Gibson's Desert»։", "58bd64e7"]},
"OLAYLAR_UMIT19_ASIRET_1119:1879-08-02:0":{"b": ["Գերհարդ Ռոլֆսի արշավախումբը մտավ Կուֆրա օազիսների արշիպելագի հյուսիսային ծայր Թայզերբո", "577b4205"], "d": ["Գերհարդ Ռոլֆսի՝ Գերմանական Աֆրիկյան ընկերության համար Տրիպոլիից դուրս եկած արշավախումբը, 1879 թ. հուլիսին Սույայի հետ կնքված պայմանագրից հետո հարավ արշավելով, գիշերը ժամը 2-ին մտավ Կուֆրայի ամենահյուսիսային կղզի Թայզերբո օազիս։ Ռոլֆսը դա նկարագրում է որպես «վերջապես հասնել խորհրդավոր Կուֆրա օազիս». իսկ Ջրանգեդի ջրհորին հասան միայն հաջորդ առավոտ ժամը 11-ին։", "ca155f46"]},
"OLAYLAR_UMIT19_ASIRET_1119:1896-12-04:0":{"b": ["Դեյվիդ Կարնեգիի ուղտային արշավախումբը հասավ Կիմբերլիի Halls Creek. հուլիսի 21-ից առաջին անգամ հանդիպեց սպիտակամորթի", "55b94bf8"], "d": ["Դեյվիդ Կարնեգիի ուղտային արշավախումբը, որ 1896 թ. հուլիսի 9-ին ճամփա էր ելել Կուլգարդիից, դեկտեմբերի 4-ին հասավ Halls Creek։ Կարնեգին գրում է, որ առաջին հանդիպած մարդը ոստիկանական սերժանտ Բրոֆին էր, և որ հուլիսի 21-ից ոչ մի սպիտակ դեմք չէին տեսել. ճանապարհորդությունը, շեղումներով հանդերձ, 1413 մղոն էր։", "82b25b9d"]}
});
